NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'Leviticus'

CHAPTERS = {
    1: {
        1: 'Og Herren ropa på Moses, og tala til honom or møtetjeldet og sagde:',
        2: '«Tala til Israels-folket og seg til deim: «Når nokon av dykk vil koma til Herren med ei offergåva av buskapen, so kann han taka offeret sitt anten av storfeet eller av småfeet.',
        3: 'Er det eit brennoffer han vil gjeva, og han tek det av storfeet, so skal det vera ein ukse som ikkje hev lyte. Til døri åt møtetjeldet skal han koma med gåva si, so han vert velsedd for Herrens åsyn,',
        4: 'og han skal leggja handi på hovudet åt offerdyret; då skal gåva hans tekkjast Herren, so han fær nåde.',
        5: 'So skal han slagta uksen for Herrens åsyn, og Arons-sønerne, prestarne, skal bera fram blodet, og skvetta det rundt ikring på altaret som stend framanfor døri åt møtetjeldet.',
        6: 'Og so skal han flå offerdyret og lema det sund;',
        7: 'og sønerne åt Aron, øvstepresten, skal kveikja upp eld på altaret, og leggja ved på elden.',
        8: 'Sidan skal Arons-sønerne, prestarne, leggja kjøtet og hovudet og feittet uppå veden som er lagd på altarelden.',
        9: 'Innvolen og føterne skal tvåast i vatn, og so skal presten brenna alt saman på altaret; so røyken stig upp mot himmelen; då er det eit brennoffer åt Herren, ein offerret som det angar godt.',
        10: 'Tek han brennofferet sitt av småfeet, av sauerne eller geiterne, so skal det vera ein lytelaus ver eller bukk.',
        11: 'Den skal han slagta på nordsida åt altaret, for Herrens åsyn, og Arons-sønerne, prestarne, skal skvetta blodet rundt ikring på altaret.',
        12: 'So skal han luta upp offerdyret, og lata hovudet og feittet fylgja med, og presten skal leggja luterne uppå veden som er lagd på altarelden.',
        13: 'Innvolen og føterne skal dei två i vatn, og so skal presten bera fram alt saman, og brenna det på altaret, so røyken stig upp mot himmelen; då er det er eit brennoffer åt Herren, ein offerret som gjev god ange.',
        14: 'Er det fugl han vil taka til brennoffer åt Herren, so skal offergåva han kjem med, vera ei turtelduva eller ein duveunge.',
        15: 'Presten skal bera fuglen fram åt altaret, og vrida hovudet av honom, og brenna det på altaret; og blodet skal kreistast ut mot altarveggen.',
        16: 'So skal han taka ut krelen med goret som er i, og kasta det attmed altaret, på austsida, der oska er,',
        17: 'og so flekkja fuglen med vengjerne på; deim må han ikkje skjera av. Sidan skal presten brenna fuglen på altaret, på veden som er lagd på elden, so røyken stig upp mot himmelen; då er det eit brennoffer åt Herren, ein offerret som anger godt.',
    },
    2: {
        1: 'Når nokon vil bera fram eit grjonoffer for Herren, so skal offergåva hans vera fint mjøl; det skal han hella olje yver og leggja røykjelse attmed,',
        2: 'og so skal han koma til Arons-sønerne, til prestarne, med det, og presten skal taka ein neve av mjølet og oljen og so all røykelsen, og brenna det på altaret, so røyken stig upp mot himmelen til ei minning; då er det ein offerret åt Herren, ein som det angar godt av.',
        3: 'Det som er att av grjonofferet, skal Aron og sønerne hans hava; det høyrer til det som er høgheilagt av offerrettarne åt Herren.',
        4: 'Når du vil bera fram eit grjonoffer av noko som er baka i omn, so skal det vera av fint mjøl, anten hellekakor med olje i eller oljesmurde tunnbrødleivar.',
        5: 'Vil du gjeva eit grjonoffer som er steikt på takka, so skal det og vera av fint mjøl som er blanda med olje, og usyrt.',
        6: 'Du skal brjota det i bitar, og hella olje yver det, so er det eit rett grjonoffer.',
        7: 'Vil du gjeva eit grjonoffer som er steikt i panna, so skal det med vera tillaga av fint mjøl og olje.',
        8: 'Når grjonofferet er tillaga på ein av dei måtarne, skal du bera det fram for Herren. Du skal koma til presten med det, og han skal bera det fram åt altaret.',
        9: 'So skal presten taka av det som skal vera til minningsoffer, og brenna det på altaret, so røyken stig upp mot himmelen; då er det ein offerret åt Herren, ein som det angar godt av.',
        10: 'Og det som då er att av offeret, skal Aron og sønerne hans hava. Det høyrer til det som er høgheilagt av Herrens offerrettar.',
        11: 'Eit grjonoffer som de ber fram for Herren, må aldri vera syrt; det som det er surdeig eller honning i, må de ikkje brenna til offermat for Herren.',
        12: 'Til nygrødeoffer kann de hava det; men på altaret må det ikkje koma, til godange for Herren.',
        13: 'Alle grjonoffer som du ber fram, skal du salta; aldri må du lata det vanta på salt i grjonofferet ditt. Saltet høyrer til sambandet med din Gud; di skal du bera fram salt attåt alle offeri dine.',
        14: 'Vil du gjeva Herren eit grjonoffer av nygrøda, so skal offeret som du ber fram av nygrøda divera aks som er steikte yver elden, eller nyhausta korn som er grøypt.',
        15: 'Det skal du hella olje yver og leggja røykjelse attmed; då er det eit rett grjonoffer.',
        16: 'Og presten skal brenna noko av det grøypte kornet og av oljen og all røykjelsen, so røyken stig upp mot himmelen til ei minning; då er det ein god offerrett for Herren.',
    },
    3: {
        1: 'Vil nokon bera fram eit takkoffer, og han tek det av storfeet, so kann det offerdyret han leider fram for Herrens åsyn vera anten ukse eller ku, men lytelaust skal det vera.',
        2: 'Han skal leggja handi på hovudet åt offerdyret, og slagta det i døri til møtetjeldet, og Arons-sønerne, prestarne, skal skvetta blodet rundt ikring på altaret.',
        3: 'So skal han av takkofferet bera fram ei gåva åt Herren, og det skal vera netja og alt feittet som er på innvolen',
        4: 'og båe nyro med talgi som er på dei og rekk burtåt låri, og den store livreflaga - den skal han skjera utor i hop med nyro -',
        5: 'og Arons-sønerne skal brenna det på altaret saman med brennofferet, som ligg på veden dei hev lagt på elden; då er det ein rjukande offerrett åt Herren, ein som gjev god ange.',
        6: 'Er det av småfeet han tek det dyret som han vil bera fram for Herren til takkoffer, so kann det vera anten han eller ho, men det skal vera fritt for lyte.',
        7: 'Vil han ofra ein sau, so skal han leida honom fram for Herrens åsyn.',
        8: 'Han skal leggja handi på hovudet åt offerdyret, og slagta det framanfor møtetjeldet, og Arons-sønerne skal skvetta blodet rundt ikring på altaret.',
        9: 'So skal han av takkofferet bera fram ei gåva for Herren, og det skal vera alt feittet som er på sauen: spælen heil og halden - den skal han skjera av tett innmed roti - og netja og alt feittet som er på innvolen,',
        10: 'og båe nyro med talgi som er på deim og rekk burtåt låri, og den store livreflaga - den skal han skjera utor i hop med nyro -',
        11: 'og presten skal brenna det på altaret; so røyken stig upp mot himmelen; det er eit godt offermål for Herren.',
        12: 'Er det ei geit han vil ofra, so skal han leida henne fram for Herrens åsyn.',
        13: 'Han skal leggja handi på hovudet hennar, og slagta henne framanfor møtetjeldet, og Arons-sønerne skal skvetta blodet rundt ikring på altaret.',
        14: 'So skal han av offeret sitt bera fram ein god rett for Herren, og det skal vera netja og alt feittet som er på innvolen',
        15: 'og båe nyro med talgi som er på deim og rekk burtåt låri, og den store livreflaga - den skal han skjera utor i hop med nyro -',
        16: 'og presten skal brenna det på altaret, so røyken stig upp mot himmelen; då er det ein offerrett som angar godt. Alt feitt høyrer Herren til.',
        17: 'Ei æveleg lov skal det vera for dykk og etterkomarane dykkar i kvar ein heim, at de aldri må eta feitt og blod.»»',
    },
    4: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Tala til Israels-folket og seg: «Når nokon uviljande syndar mot eit av Herrens bod og gjer noko som han hev forbode å gjera, so høyr:',
        3: 'Er det den salva presten som syndar og fører skuld yver folket, so skal han til bot for den syndi han hev gjort koma til Herren med ein ung ukse som ikkje hev lyte; det skal vera syndofferet hans.',
        4: 'Han skal leida uksen fram for Herrens åsyn, til døri åt møtetjeldet, og han skal leggja handi på hovudet åt uksen, og han skal slagta uksen for Herrens åsyn.',
        5: 'So skal han, den salva presten, taka noko av ukseblodet og bera det inn i møtetjeldet.',
        6: 'Og han, presten, skal duppa fingeren i blodet, og han skal skvetta av blodet sju gonger for Herrens åsyn, framanfor det heilage forhenget.',
        7: 'Noko av blodet skal han strjuka på horni åt altaret med den angande røykjelsen, det som stend framfor Herrens åsyn i møtetjeldet, og det som er att av ukseblodet, skal han hella ut tett innmed foten på brennofferaltaret, som stend framanfor døri til møtetjeldet.',
        8: 'Alt feittet som er på syndofferuksen, skal han taka utor honom, både netja og alt feittet som er på innvolen',
        9: 'og båe nyro med talgi som er på deim og rekk burtåt låri, og den store livreflaga - den skal han skjera utor i hop med nyro -',
        10: 'alt dette skal han taka ut, like eins som på takkofferuksen, og so skal han brenna det på brennofferaltaret, so røyken stig upp mot himmelen.',
        11: 'Men hudi av uksen og alt kjøtet, med hovudet og føterne og innvolen og myki,',
        12: 'heile uksen, skal han føra ut or lægret, til ein rein stad, der dei slær ut oska, og brenna det upp med ved; der som oska vert slegi ut, der skal dei brenna det.',
        13: 'Hev heile Israels-lyden misfare seg, hev folket seg uvitande gjort noko av det som Herren hev forbode å gjera, og ført skuld yver seg,',
        14: 'og det sidan vert kunnigt kva dei hev synda i, so skal folket koma med ein ung ukse til syndoffer. Den skal dei leida fram åt møtetjeldet,',
        15: 'og dei eldste av lyden skal leggja henderne på hovudet åt uksen for Herrens åsyn, og so skal uksen slagtast for Herrens åsyn.',
        16: 'Den salva presten skal bera noko av ukseblodet inn i møtetjeldet,',
        17: 'og han, presten, skal duppa fingeren i blodet, og skvetta sju gonger for Herrens åsyn, framanfor forhenget.',
        18: 'Noko av blodet skal han strjuka på horni åt det altaret som stend framfor Herrens åsyn i møtetjeldet, og det som er att av blodet, skal han hella ut tett innmed foten på brennofferaltaret, som stend framanfor døri til møtetjeldet.',
        19: 'Alt feittet skal han taka utor uksen, og brenna det på altaret, so røyken stig upp mot himmelen.',
        20: 'Som han gjorde med hin syndofferuksen, so skal han gjera med denne og. Når presten soleis hev bore fram soningsoffer for deim, skal dei få tilgjeving.',
        21: 'Sidan skal dei føra uksen utanfor lægret, og brenna honom, liksom dei brende den fyrste uksen. Dette er syndofferet for folket.',
        22: 'Når ein hovding misfer seg og uviljande gjer noko av det som Herren, hans Gud, hev forbode å gjera, og soleis fører skuld yver seg,',
        23: 'og det vert kunnigt for honom kva han hev synda i, so skal han koma med ei offergåva, og det skal vera ein geitebukk, ein som ikkje hev lyte.',
        24: 'Han skal leggja handi på hovudet åt bukken, og slagta honom på same staden som dei slagtar brennofferet for Herrens åsyn; då er det eit syndoffer.',
        25: 'Presten skal taka noko av offerblodet på fingeren, og strjuka det på horni åt brennofferaltaret, og det som er att av blodet, skal han hella ut tett innmed foten på brennofferaltaret.',
        26: 'Og alt feittet skal han brenna på altaret liksom han gjorde med feittet av takkofferet. Når presten soleis hev bore fram soningsoffer for honom og gjort honom rein for syndi, skal han få tilgjeving.',
        27: 'Er det ein ålmugemann som uviljande syndar mot eit av Herrens bod og gjer noko som han ikkje skulde gjera, so han fører skuld yver seg,',
        28: 'og det vert kunnigt for honom kva han hev synda i, so skal han til bot for den syndi han hev gjort, koma med ei offergåva, og det skal vera ei geit, ei som ikkje hev lyte.',
        29: 'Han skal leggja handi på hovudet åt syndofferdyret, og han skal slagta syndofferdyret på brennofferstaden.',
        30: 'Og presten skal taka noko av blodet på fingeren, og strjuka det på horni åt brennofferaltaret, og det som er att av blodet, skal han hella ut tett innmed altarfoten.',
        31: 'Alt feittet skal han taka utor, liksom dei tek ut feittet på takkofferet, og presten skal leggja det på altaret og brenna det til godange for Herren. Når presten soleis hev gjort soning for honom, skal han få tilgjeving.',
        32: 'Vil han heller taka ein sau til syndoffer, so skal han koma med ei søya som ikkje hev lyte.',
        33: 'Han skal leggja handi på hovudet åt offerdyret, og so skal han slagta det til syndoffer på same staden som dei slagtar brennofferet.',
        34: 'Og presten skal taka noko av syndofferblodet på fingeren, og strjuka det på horni åt brennofferaltaret, og det som er att av blodet, skal han hella ut tett innmed altarfoten.',
        35: 'Alt feittet skal han taka utor, liksom dei gjer med takkoffersauen, og presten skal brenna det på altaret saman med offerretterne åt Herren. Når presten soleis hev bore fram soningsoffer for den syndi han hev gjort, skal han få tilgjeving.',
    },
    5: {
        1: 'Når nokon høyrer ei våbøn som vert lyst yver ein brotsmann, og han hev set eller veit noko so han kunde vitna mot honom, men like vel ikkje segjer ifrå, og soleis syndar og fører skuld yver seg,',
        2: 'eller nokon, seg uvitande, kjem innåt noko ureint, anten det er etslet av eit ureint villdyr eller av eit ureint krøter eller av eit ureint krek, og soleis sjølv vert urein og fører skuld yver seg,',
        3: 'eller når han kjem nær noko ureint av folk, kva det so er for ureinska som er på deim, og han ikkje veit av det, men sidan fær vita det og ser at han hev ført skuld yver seg,',
        4: 'eller når nokon sver tankelaust burt i veret at han vil gjera eitt eller anna, slikt som folk kann koma til å sverja på i tankeløysa, og han ikkje håttar det, men sidan vert vis med at han hev ført skuld yver seg med eitkvart sovore,',
        5: 'so skal den som soleis hev ført skuld yver seg standa til kva han hev synda i,',
        6: 'og til bot for den syndi han hev gjort, skal han koma til Herren med eit syndoffer - det skal vera eit småkrøter av hoslaget, søya eller geit - og presten skal bera fram soningsoffer for honom og gjer honom rein for syndi.',
        7: 'Hev han ikkje råd til eit småkrøter, so skal han til bot for den syndi han hev gjort bera fram for Herren tvo turtelduvor eller tvo duveungar, den eine til syndoffer og den andre til brennoffer.',
        8: 'Han skal koma til presten med deim, og presten skal fyrst bera fram den duva som skal vera til syndoffer. Han skal vrida um hovudet på henne tett uppmed nakken, men ikkje skilja det frå bulen.',
        9: 'So skal han skvetta noko av syndofferblodet på altarveggen, og det som er att av blodet, skal kreistast ut so det renn ned innmed altarfoten. Då er det eit rett syndoffer.',
        10: 'Av den andre duva skal han laga til eit brennoffer, på rette gjerdi. Når presten soleis hev bore fram soningsoffer for den syndi han hev gjort, so skal han få tilgjeving.',
        11: 'Hev han ikkje råd til tvo turtelduvor eller tvo duveungar, so skal han til bot for di han hev synda koma med ei kanna fint mjøl; det skal vera syndofferet hans. Han skal ikkje hava olje på det, og ikkje leggja røykjelse attmed; for det er eit syndoffer.',
        12: 'Til presten skal han koma med det, og presten skal taka ein neve av mjølet og brenna på altaret, saman med offerretterne åt Herren, då er det eit rett syndoffer.',
        13: 'Når presten soleis hev bore fram soningsoffer for den syndi han på den eine eller den andre måten hev gjort, so skal han få tilgjeving. Dette offeret skal høyra presten til på same vis som grjonofferet.»»',
        14: 'Og Herren tala atter til Moses, og sagde:',
        15: '«Er det nokon som uviljande eignar til seg noko av det som er vigt åt Herren, og soleis vert saka i svik, so skal han til bot for si skuld koma til Herren med ein lytelaus ver av fenaden sin, ein som etter ditt skyn er verd minst tvo sylvdalar i heilag mynt; det skal vera skuldofferet hans.',
        16: 'Det han med urett hev eigna til seg av dei vigde gåvorne, skal han gjeva att, og attåt leggja femteparten av verdet. Han skal gjeva det til presten, og når presten hev ofra skuldofferveren til soning for honom, skal han få tilgjeving.',
        17: 'Når nokon syndar og gjer noko av det som Herren hev forbode å gjera, og han ikkje veit av det, men skynar at han hev fare i mist og ført skuld yver seg,',
        18: 'so skal han til bot for si skuld koma til presten med ein lytelaus ver av fenaden sin, ein som etter ditt skyn er eit fullgodt offer; og presten skal bera fram soningsoffer for den misgjerdi han hev gjort og ikkje visste av, og då skal han få tilgjeving.',
        19: 'Dette er eit skuldoffer; for det var visst at han bar på ei skuld imot Herren.» Og Herren tala atter til Moses, og sagde: «Når nokon syndar og gjer svik imot Herren og dyl burt noko som grannen hev gjeve honom i varveitsla eller sett i vissa hjå honom, eller som han hev teke eller truga til seg av grannen, eller han finn noko som ein annan hev mist og so dyl det, eller når han gjer rang eid um eitt eller anna som han eller andre kann ha synda med, so skal den som soleis hev synda og ført skuld yver seg, gjeva att det han hev teke, eller truga til seg, eller fenge i varveitsla eller funne, og det han hev gjort rang eid um, kva det no kann vera. Han skal gjeva det att med fullt verd, og leggja femteparten attåt; til eigarmannen skal han gjeva det, og det same dagen som han ber fram skuldofferet sitt. Og til bot for si skuld skal han koma til Herren med ein lytelaus ver av fenaden sin, ein som etter ditt skyn er eit fullgodt offer, og gjeva honom til presten; det skal vera skuldofferet hans. So skal presten gjera soning for honom for Herrens åsyn, og då skal han få tilgjeving for alle gjerningar som han kann ha ført skuld yver seg med.»',
    },
    6: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Seg til Aron og sønerne hans: «So er lovi um brennofferet: Brennofferet det skal liggja på eldstaden sin, på altaret, heile natti, til morgons, og der skal altarelden nørast.',
        3: 'Og presten skal klæda seg i linkjolen sin, og ei linbrok skal han hava på seg næst kroppen, og han skal taka burt oska etter brennofferet, som elden hev tært upp på altaret, og leggja henne attmed altaret.',
        4: 'So skal han hava av seg klædebunaden sin, og taka på seg andre klæde, og bera oska ut or lægret, til ein rein stad.',
        5: 'Men elden skal haldast vaken på altaret; han må ikkje slokna. Kvar morgon skal presten nøra elden med ved, og leggja brennofferet uppå veden, og saman med det brenna takkofferfeittet, so røyken stig upp mot himmelen.',
        6: 'Elden skal allstødt brenna på altaret, og må aldri slokna.',
        7: 'So er lovi um grjonofferet: Ein av Arons-sønerne skal bera det fram for Herren, på altaret.',
        8: 'Han skal taka ein neve av det fine mjølet og oljen i grjonofferet, og all røykjelsen som fylgjer med grjonofferet, og brenna det på altaret, so røykjen stig upp mot himmelen; det er eit minningsoffer åt Herren, eit som gjev god ange.',
        9: 'Og det som er att av offeret, skal Aron og sønerne hans eta; det skal etast usyrt på ein heilag stad: i tunet åt møtetjeldet skal dei eta det;',
        10: 'med surdeig må det ikkje bakast. Det er den luten eg gjev deim av offerretterne mine; høgheilagt er det, liksom syndofferet og skuldofferet.',
        11: 'Alle menner som er ætta frå Aron, må eta av det; gjenom alle tider og ætter skal det vera dykkar rett av offergåvorne åt Herren; den som rører deim, lyt vera vigd.»»',
        12: 'Og Herren tala atter til Moses, og sagde:',
        13: '«Den offergåva som Aron og sønerne hans skal bera fram for Herren den dagen dei vert salva, det er ei kanna fint mjøl; det skal vera det dagvisse grjonofferet, helvti um morgonen og helvti um kvelden.',
        14: 'Med olje skal det lagast til på ei takka; godt knoda skal det vera når du kjem med det; eit grjonoffer som er sundbytt i småstykke, skal du bera fram til godange for Herren.',
        15: 'Den av sønerne åt Aron som vert salva til prest i staden hans, skal laga det til. Ei æveleg reidda åt Herren skal det vera, og heile offeret skal brennast.',
        16: 'Alle prestegrjonoffer skal vera heiloffer; dei må ikkje etast.»',
        17: 'Og Herren tala atter til Moses, og sagde:',
        18: '«Tala til Aron og sønerne hans og seg: «So er lovi um syndofferet: På same staden som dei slagtar brennofferet, skal syndofferet og slagtast for Herrens åsyn; høgheilagt er det.',
        19: 'Presten som ber fram syndofferet, må eta det; på ein heilag stad skal det etast, i møtetjeldtunet.',
        20: 'Den som rører offerkjøtet, lyt vera vigd. Kjem det noko av blodet på klædi, so skal du taka det plagget som blodet hev kome på og två det på ein heilag stad.',
        21: 'Er det ei leirgryta kjøtet vert koka i, so skal ho slåast sund; men er det ein koparkjel, so skal han skurast og skyljast med vatn.',
        22: 'Alle menner som er prestar, må eta av dette offeret; det er høgheilagt.',
        23: 'Men dei syndofferi som det vert bore blod av inn i møtetjeldet til å sona med i heilagdomen, dei må aldri etast; dei skal brennast i elden.',
    },
    7: {
        1: 'So er lovi um skuldofferet: Det er høgheilagt.',
        2: 'På same staden som dei slagtar brennofferet, skal dei slagta skuldofferet. Blodet skal dei skvetta rundt ikring på altaret,',
        3: 'og alt feittet skal dei bera fram for Herren, både spælen og netja,',
        4: 'og båe nyro med talgi som er på deim og rekk burtåt låri, og den store livreflaga - den skal skjerast utor i hop med nyro -',
        5: 'og presten skal brenna det på altaret til ein offerrett for Herren; då er det eit rett skuldoffer.',
        6: 'Alle menner som er prestar, må eta av det; på ein heilag stad skal det etast; det er høgheilagt.',
        7: 'Med skuldofferet er det like eins som med syndofferet - det gjeld same lovi for båe; den presten som gjer soning med det, han skal hava det.',
        8: 'Når ein prest ofrar brennoffer for ein mann, so skal den same presten hava hudi av offerdyret som han hev bore fram.',
        9: 'Og alle grjonoffer som vert baka i omn og alle som er tillaga i panna eller på takka, deim skal den presten hava som ber deim fram.',
        10: 'Men alle andre grjonoffer, anten dei er blanda med olje eller turre, skal høyra alle Arons-sønerne til, den eine som den andre.',
        11: 'So er den lovi som gjeld når nokon kjem til Herren med eit takkoffer:',
        12: 'Er det til Guds lov og pris han ofrar det, so skal han attåt slagtofferet bera fram hellekakor med olje i, og tunnbrødleivar som er smurde med olje, og fint mjøl som er blanda med olje og knoda til kakor.',
        13: 'Det er dei offergåvorne han skal bera fram attåt lov- og takkofferdyret, og umfram det skal han hava med seg syrte kakor.',
        14: 'Av offergåvorne skal han gjeva ei av kvart slag i reida åt Herren; det skal presten hava, han som skvetter blodet av takkofferet på altaret.',
        15: 'Kjøtet av lov- og takkofferet lyt etast same dagen som det vert frambore; ingen må gøyma noko av det til morgons.',
        16: 'Er det eit slagtoffer som ein hev lova eller gjev i godvilje, so skal det helst etast same dagen som han ber fram offeret sitt. Vert det noko att, so kann det etast dagen etter.',
        17: 'Men det som er att av offerkjøtet tridje dagen, skal brennast upp i elden.',
        18: 'Dersom nokon et av takkofferkjøtet tridje dagen, so hev Herren ingen hugnad i offeret, og det vert ikkje rekna den til gode som bar det fram; det skal haldast for utskjemt og ureint, og den som et av det, gjer ei misgjerning som han kjem til å lida for.',
        19: 'Kjøt som hev vore innåt noko ureint, må heller ikkje etast; det skal brennast upp i elden. Elles kann alle som er reine eta av kjøtet.',
        20: 'Men den som et kjøt av Herrens takkoffer medan det er noko ureint på honom, han skal rydjast ut or ætti si.',
        21: 'Og når ein mann kjem nær noko ureint, anten det er slik ureinska som kann vera på folk, eller det er eit ureint dyr eller noko anna ureint og ufyse, og han so et av takkofferkjøtet åt Herren, so skal den mannen rydjast ut or ætti si.»»',
        22: 'Og Herren tala atter til Moses, og sagde:',
        23: '«Tala til Israels-borni og seg: «De må aldri eta feitt, anten av ukse eller sau eller geit.',
        24: 'Feittet av sjølvdaude dyr og av dyr som er rivne i hel, kann de nytta til ymse ting, men eta det må de ikkje.',
        25: 'Er det nokon som et feittet av slikt bufe som dei tek til offer åt Herren, so skal den som gjer det rydjast ut or ætti si.',
        26: 'Og ikkje i noko hus må de eta blod, anten av fugl eller fe.',
        27: 'Den som nokosinne et blod, han skal rydjast ut or ætti si.»»',
        28: 'Og Herren tala atter til Moses, og sagde:',
        29: '«Tala til Israels-borni og seg: «Den som vil bera fram eit takkeslagtoffer åt Herren, han skal sjølv koma med det han vil gjeva Herren av offeret sitt.',
        30: 'Med sine eigne hender skal han bera fram dei offerretterne som er etla åt Herren. Både bringestykket og feittet skal han bera fram, og bringestykket skal svingast att og fram for Herrens åsyn.',
        31: 'Og presten skal brenna feittet på altaret, so røyken stig upp mot himmelen; men bringestykket skal Aron og sønerne hans hava.',
        32: 'Og det høgre låret skal de gjeva presten i reida av takkofferi dykkar:',
        33: 'den av Arons-sønerne som ber fram takkofferblodet og feittet, han skal hava det høgre låret for sin lut.',
        34: 'For svingebringa og lyftelåret av takkeofferi frå Israels-folket tek eg imot av deim, og gjev det åt Aron, presten, og sønerne hans; det skal i all æva vera retten deira av Israels-folket.»»',
        35: 'So var den luten Aron og sønerne hans fekk av Herrens offerretter den dagen dei vart kalla til å gjera prestetenesta for Herren;',
        36: 'det var det Herren sagde at Israels-borni skulde gjeve deim den dagen dei vart salva, og det skulde vera retten deira ætt etter ætt i all æva.',
        37: 'Dette var lovi um brennofferet og um grjonofferet og um syndofferet og um skuldofferet og um vigsleofferet og um takkofferet,',
        38: 'den som Herren kunngjorde for Moses på Sinaifjellet, den gongen han gav Israels-folket det bodet at dei skulde bera fram offergåvorne sine for Herren i øydemarki kring Sinai.',
    },
    8: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Henta no Aron og sønerne hans, og tak dei heilage klædi og salvingsoljen og syndofferuksen og båe verarne og korgi med søtebrødet,',
        3: 'og kalla so heile lyden saman framfor døri åt møtetjeldet!»',
        4: 'Og Moses gjorde som Herren sagde, og lyden samla seg framfor møtetjelddøri.',
        5: 'Då sagde Moses til deim: «Sjå no kva Herren hev sagt eg skal gjera!»',
        6: 'So kalla han til seg Aron og sønerne hans, og tvo dei med vatn,',
        7: 'og han hadde underkjolen på Aron, og spente beltet um honom, og klædde honom i prestekjolen, og hengde messehakelen på honom, og batt um honom livgjordi som høyrde til, og med den snørde han messehakelen fast.',
        8: 'So hadde han bringeduken på honom, og i bringeduken lagde han urim og tummim.',
        9: 'Og han sette huva på hovudet hans, og framme på huva sette han gullspongi, det heilage hovudgullet, alt soleis som Herren hadde sagt med Moses.',
        10: 'So tok Moses salvingsoljen, og salva gudshuset og alt som i det var, og vigsla det,',
        11: 'og han skvette sju vendor på altaret av oljen, og salva altaret og alle dei ting som høyrde til det, og tvåttebalja med foten ho stod på, og vigsla deim.',
        12: 'Og noko av salvingsoljen helte han yver hovudet på Aron, og salva og vigde honom.',
        13: 'Sidan kalla han til seg sønerne hans Aron, og klædde deim i underkjolar, og spente belte um deim, og batt hovudplagg på deim, alt soleis som Herren hadde sagt med Moses.',
        14: 'So leidde han fram syndofferuksen, og Aron og sønerne hans lagde henderne på hovudet åt uksen.',
        15: 'Og då dei hadde slagta honom, tok Moses blodet og strauk rundt ikring på altarhorni med fingeren, og gjorde altaret reint for synd, og det som var att av blodet, helte han ut tett innmed altarfoten. Soleis gjorde han soning for altaret og vigsla det.',
        16: 'So tok han alt feittet som var på innvolen, og den store livreflaga og båe nyro med talgi på, og brende det på altaret, so røyken steig upp mot himmelen.',
        17: 'Men sjølve uksen, både hudi og kjøtet og møki, brende han i elden utanfor lægret, alt soleis som Herren hadde sagt med Moses.',
        18: 'So leidde han fram brennofferveren, og Aron og sønerne hans lagde henderne på hovudet åt veren.',
        19: 'Og då dei hadde slagta honom, skvette Moses blodet rundt ikring på altaret.',
        20: 'Men sjølve veren lema dei sund, og Moses brende hovudet og kjøtet og feittet;',
        21: 'innvolen og føterne tvo dei fyrst i vatn, og so brende Moses heile veren på altaret, so røyken steig upp mot himmelen. Det vart eit brennoffer som anga godt, ein offerrett for Herren var det; alt vart gjort soleis som Herren hadde sagt med Moses.',
        22: 'So leidde han fram den andre veren, vigsleveren, og Aron og sønerne hans lagde henderne på hovudet åt veren.',
        23: 'Og då dei hadde slagta honom, tok Moses noko av blodet og strauk på den høgre øyresnippen åt Aron og på den høgre tumarsfingeren og den høgre tumarståi hans.',
        24: 'So kalla han til seg sønerne hans Aron, og strauk noko av blodet på den høgre øyresnippen og på den høgre tumarsfingeren og den høgre tumarståi deira, og det som var att av blodet, skvette han rundt ikring på altaret.',
        25: 'Og han tok feittet, både spælen alt feittet som var på innvolen, og den store livreflaga og båe nyro med talgi på, og so det høgre låret.',
        26: 'Og or søtebrødkorgi som stod framfor augo åt Herren, tok han ei hellekake og eit oljebrød og ein tunnbrødleiv og lagde uppå på feittet og verlåret.',
        27: 'Og so lagde han alt saman i henderne på Aron og sønerne hans og svinga det att og fram for Herrens åsyn.',
        28: 'Sidan tok han det utor henderne deira, og brende det på altaret saman med brennofferet, so røyken steig upp mot himmelen; det var eit vigsleoffer som gav god ange, ein offerrett for Herren var det.',
        29: 'Og Moses tok bringestykket, og svinga det att og fram for Herrens åsyn; det var den luten Moses fekk av vigsleveren, soleis som Herren hadde sagt med Moses.',
        30: 'So tok Moses noko av salvingsoljen og noko av blodet som stod på altaret og skvette på Aron og klædi hans og på sønerne hans og klædi deira; og vigsla Aron og klædi hans og sameleis sønerne hans og klædi deira.',
        31: 'Og Moses sagde til Aron og sønerne hans: «De skal sjoda kjøtet i døri åt møtetjeldet og eta det attåt brødet som er i vigsleofferkorgi; for so hev Gud sagt med meg: «Aron og sønerne hans skal eta det,» hev han sagt.',
        32: 'Men det som vert att av kjøt og brød, skal de brenna i elden.',
        33: 'Og so lyt de i sju dagar halda dykk innmed møtetjelddøri, alt til den dagen då vigsletidi dykkar er ute; for sju dagar skal prestevigsla vara.',
        34: 'Som de hev gjort i dag, so skal de gjera dei hine dagarne og, so de kann få nåde, segjer Herren.',
        35: 'Og i møtetjelddøri skal de sitja dag og natt i sju jamdøger og halda dykk etter det som Herren hev sagt, so de ikkje skal missa livet; for so hev Herren sagt med meg.»',
        36: 'Og Aron og sønerne hans gjorde alt det som Herren hadde late Moses segja til deim.',
    },
    9: {
        1: 'Då den åttande dagen var komen, kalla Moses til seg Aron og sønerne hans og dei øvste i Israel,',
        2: 'og han sagde med Aron: «Tak ein uksekalv til syndoffer og ein ver til brennoffer, lytelause båe tvo, og leid deim fram for Herrens åsyn!',
        3: 'Og til Israels-folket skal du segja: «Tak ein geitebukk til syndoffer, og ein kalv og eit lamb, årsgamle og lytelause båe tvo, til brennoffer,',
        4: 'og ein ukse og ein ver til takkoffer - dei skal slagtast for Herrens åsyn - og so eit grjonoffer som er tillaga med olje! For i dag vil Herren syna seg for dykk.»»',
        5: 'So henta dei det som Moses hadde sagt, og sette det framanfor møtetjeldet, og heile lyden gjekk innåt, og stod for Herrens åsyn.',
        6: 'Og Moses sagde: «Soleis hev Herren sagt de skal gjera, so skal herlegdomen åt Herren syna seg for dykk.»',
        7: 'So sagde han til Aron: «Kom hit åt altaret, og ofra syndofferet og brennofferet ditt, og gjer soning for deg og for folket, og ber so fram offergåva frå folket og gjer soning for deim, soleis som Herren hev sagt!»',
        8: 'So steig Aron fram åt altaret, og slagta uksekalven som skulde vera syndoffer for honom sjølv.',
        9: 'Sønerne hans gav honom blodet, og han duppa fingeren i blodet, og strauk det på altaret, og det som var att av blodet, helte han ut tett innmed altarfoten.',
        10: 'Feittet og nyro og den store livreflaga av syndofferdyret brende han på altaret, so røyken steig upp mot himmelen, soleis som Herren hadde sagt med Moses;',
        11: 'men kjøtet og hudi brende han i elden utanfor lægret.',
        12: 'So slagta han brennofferdyret. Sønerne hans gav honom blodet, og han skvette det rundt ikring på altaret.',
        13: 'Sidan rette dei sjølve brennofferet til honom, stykke for stykke, og hovudet, og han brende det på altaret, so røyken steig upp mot himmelen.',
        14: 'Innvolen og føterne tvo han i vatn, og so brende han det og på altaret i hop med hitt.',
        15: 'So bar han fram offergåvorne frå folket. Fyrst tok han bukken som skulde vera syndoffer for folket, og slagta honom, og bar honom fram til syndoffer, liksom det fyrste offerdyret.',
        16: 'Sameleis førde han fram brennofferet, og stelte det til på rette gjerdi.',
        17: 'Sidan bar han fram grjonofferet; av det tok han ein neve og brende på altaret umfram morgon-brennofferet.',
        18: 'So slagta han uksen og veren, takkofferet frå folket; sønerne hans gav honom blodet, og han skvette det rundt ikring på altaret.',
        19: 'Og feittet av uksen, og spælen og netja og nyro og den store livreflaga av veren,',
        20: 'alt feittet, lagde dei uppå bringestykki. Og Aron brende feittet på altaret, so røyken steig upp mot himmelen;',
        21: 'men bringestykki og det høgre låret svinga han att og fram for Herrens åsyn, som Moses hadde sagt til honom.',
        22: 'Og Aron lyfte henderne yver folket og velsigna deim, og so steig han ned, etter han hadde bore fram syndofferet og brennofferet og takkofferet.',
        23: 'Sidan gjekk Moses og Aron inn i møtetjeldet, og då dei kom ut att, velsigna dei folket. Då synte herlegdomen åt Herren seg for heile folket,',
        24: 'og det for eld ut frå Herren åsyn og brende upp det som var på altaret, både brennofferet og feittet, og då folket såg det, ropa dei alle høgt av gleda, og kasta seg ned, med andlitet mot jordi.',
    },
    10: {
        1: 'Men tvo av Arons-sønerne, Nadab og Abihu, tok kvar sitt glodfat og hadde gløder i, og lagde røykjelse på gløderne, og bar framand eld fram for Herrens åsyn, det som han hadde forbode deim.',
        2: 'Då for det eld ut frå Herren og tynte deim, og dei døydde for Herrens åsyn.',
        3: 'Og Moses sagde med Aron: «Dette var det Herren meinte då han sagde: «Min heilagdom eg syner på deim som er meg næst, og alt folket let eg mitt velde lysa fram.»» Og Aron tagde.',
        4: 'Men Moses ropa på Misjael og Elsafan, sønerne hans Uzziel, som var farbror åt Aron, og sagde med deim: «Kom hit, og ber frendarne dykkar burt frå heilagdomen og ut or lægret!»',
        5: 'So kom dei, og gjorde som Moses sagde, og bar deim ut or lægret i kjolarne deira.',
        6: 'Og Moses sagde til Aron og til Eleazar og Itamar, sønerne hans: «De skal ikkje ganga med uflitt hår og ikkje riva sund klædi dykkar; for då kjem de til å missa livet, og han vert vreid på heile lyden. Men brørne dykkar, heile Israels-ætti, må gråta yver den elden som Herren sende.',
        7: 'Og frå møtetjelddøri må de ikkje røyva dykk, so sant de ikkje vil missa livet; for Herrens salvingsolje er på dykk.» Og dei gjorde som Moses sagde.',
        8: 'Og Herren tala til Aron, og sagde:',
        9: '«Vin eller nokon sterk drykk må du og sønerne dine ikkje drikka, når de gjeng inn i møtetjeldet; for då kjem de til å missa livet. Det skal vera ei æveleg lov for deg og etterkomarane dine,',
        10: 'so de kann skilja millom heilagt og vanheilagt og millom ureint og reint,',
        11: 'og læra Israels-folket alle dei bodi som Herren hev late Moses kunngjera for deim».',
        12: 'Sidan sagde Moses til Aron og til Eleazar og Itamar, deim av sønerne hans som var i live: «Tak det som er att av dei grjonofferi det hev bore fram for Herren, og et det usyrte frammed altaret; for det er høgheilagt.',
        13: 'De skal eta det på ein heilag stad; det er det som du og sønerne dine hev rett til av offergåvorne åt Herren; for so hev Herren sagt med meg.',
        14: 'Og svingebringa og lyftelåret skal de og eta på ein rein stad, du og sønerne og døtterne dine med deg; for det er den luten som er gjeven deg og borni dine av takkofferi frå Israels-folket.',
        15: 'Både lyftelåret og svingebringa skal dei bera fram i hop med offerfeittet, og svinga det att og fram for Herrens åsyn; sidan skal det høyra deg og borni dine til, og vera retten dykkar æveleg og alltid, soleis som Herren hev sagt.»',
        16: 'Då Moses tok til å spyrja etter syndofferbukken, fekk han vita at han var uppbrend. Då vart han harm på Eleazar og Itamar, deim som var att av sønerne hans Aron, og han sagde:',
        17: '«Kvi hev de ikkje ete syndofferet på den heilage staden? De veit då det er høgheilagt, og han hev gjeve dykk det på den måten at de skal taka burt syndeskuldi frå lyden og gjera soning for deim hjå Herren.',
        18: 'Blodet vart ikkje bore innar i heilagdomen; difor skulde de ha ete offerkjøtet på den heilage staden, som eg sagde dykk.»',
        19: 'Då svara Aron: «Du veit at dei i dag hev bore fram syndofferet og brennofferet sitt for Herrens åsyn, og endå hev slik ei ulukka hendt meg. Um eg no hadde ete syndoffer i dag, trur du då Herren hadde tykt vel um det?»',
        20: 'Då Moses høyrde det, tykte han det var rett.',
    },
    11: {
        1: 'Og Herren tala atter til Moses og Aron, og sagde med deim:',
        2: '«Tala til Israels-folket og seg: «Høyr no kva det er for nokre de må eta av alle dei firføtte dyri som liver på jordi:',
        3: 'Alle dyr som hev klauver og jortar, deim kann de eta.',
        4: 'Det er berre desse de ikkje må eta av deim som jortar og av dei som hev klauver: kamelen, for han jortar, men hev ikkje klauver; han skal vera urein for dykk,',
        5: 'og bergtassen, for han og jortar, men hev ingi klauver; han skal vera urein for dykk,',
        6: 'og haren, for um han jortar, so hev han ikkje klauver han heller; han skal vera urein for dykk,',
        7: 'og svinet, for det hev klauver, men det jortar ikkje; det skal vera ureint for dykk.',
        8: 'Kjøtet deira må de ikkje eta, og er dei daude, so må de ikkje røyva deim; dei skal vera ureine for dykk.',
        9: 'Høyr so kva de må eta av det som er i vatnet: Alt som er i vatnet, i havet og i elvarne, og hev uggar og reist, kann de eta.',
        10: 'Men slikt som ikkje hev uggar og reist av alt det som finst i hav eller å, av alt det som yrer i vatnet, alle kvikjende som held til der, det skal vera ein styggedom for dykk.',
        11: 'Ein styggedom skal dei vera for dykk; kjøtet deira må de ikkje eta, og er dei daude, so skal de styggjast ved kropparne deira.',
        12: 'Alt i vatnet som ikkje hev uggar og reist, skal vera ein styggedom for dykk.',
        13: 'Høyr no og kva det er for fuglar de skal hava stygg til og ikkje må eta, av di dei er ufysne: Ørnen og gribben og sjøørnen',
        14: 'og glenta og heile falkeætti',
        15: 'og alle fuglar av ramneætti',
        16: 'og strussen og gauken og måsen og alle haukeslag',
        17: 'og kattula og kavfuglen og stunulven',
        18: 'og kveldknarren og pelikanen og etslegribben',
        19: 'og storken og heidloi med alle andre fuglar av same ætti, og herfuglen og skinnvengja.',
        20: 'Alt krek som hev vengjer og krabbar på marki, skal vera ein styggedom for dykk:',
        21: 'Av alt sovore krek må de ikkje eta anna enn det som ovanfor bakføterne hev leggjer til å hoppa på marki med.',
        22: 'Av det kann de eta dei slagi som dei kallar fljugaren og slukaren og springaren og sprettaren.',
        23: 'Men alt anna krek som hev vengjer og krabbar på marki, skal vera ein styggedom for dykk.',
        24: 'No skal eg segja dykk kva det er for dyr de vert ureine av - den som kjem nær kroppen deira etter dei er daude, han er urein alt til kvelds,',
        25: 'og den som hev bore på slik ein daud kropp, lyt två klædi sine, og er urein alt til kvelds -:',
        26: 'Alle dyr som hev høver, og ikkje klauver, og som ikkje jortar, skal vera ureine for dykk; den som kjem nær deim, vert urein.',
        27: 'Og alle firføtte dyr som gjeng på labbar, skal vera ureine for dykk; den som kjem nær deim når dei er daude, han er urein alt til kvelds,',
        28: 'og den som hev bore på slikt eit daudt dyr, lyt två klædi sine, og er urein alt til kvelds. Ureine skal dei vera for dykk.',
        29: 'Av alle smådyr som røyver seg på jordi er det fyrst og fremst desse som skal vera ureine for dykk: Røysekatten og musi og alle fjorføtleslag,',
        30: 'og bustyvelen og vonden og padda og snigelen og litkvervingen.',
        31: 'Deim skal de halda for dei ureinaste av alle smådyr; den som kjem nær deim når dei er daude, er urein alt til kvelds.',
        32: 'Og alt det som dei dyri dett ned på når dei daudar, vert ureint, både trekoppar og klæde og skinn og sekkjer og kva det elles er som vert nytta i huset; det skal leggjast i vatn, og er ureint alt til kvelds; sidan er det reint.',
        33: 'Dett eit av dyri ned i ein leirkopp, so vert alt det som er i koppen ureint, og han skal slåast sund.',
        34: 'All mat som folk et, og som vert tillaga med vatn, og alt drikka som folk drikk, vert ureint, kva kjerald det er i.',
        35: 'Alt det som slik ein daud kropp dett ned i, vert ureint; er det ein bakaromn eller ei eisa, so skal dei rivast ned; dei er ureine, og skal vera ureine for dykk.',
        36: 'Berre kjeldor og brunnar som det renn vatn åt, er like reine; men den som tek i den daude kroppen som ligg der, vert urein.',
        37: 'Dett dyret ned i korn som skal vera til såfrø, so er kornet like reint,',
        38: 'men hev dei havt vatn på det, og det so dett slikt eit daudt dyr ned i, so skal kornet vera ureint for dykk.',
        39: 'Daudar noko av dei dyri som skal vera til føda for dykk, so er den som kjem nær skrotten deira urein alt til kvelds,',
        40: 'den som hev ete av kjøtet deira, lyt två klædi sine, og er urein alt til kvelds, og den som hev bore på den daude skrotten, lyt og två klædi sine og er urein alt til kvelds.',
        41: 'Alt kreket som krelar på marki, er ein styggedom, og må ikkje etast.',
        42: 'Korkje det som skrid på buken, eller det som gjeng på fire eller fleire føter, må de eta; for det er ufyse.',
        43: 'Gjer dykk ikkje sjølve ufysne med noko av det krelande kreket, og sulka dykk ikkje med det, so de vert ureine!',
        44: 'Eg, Herren, er dykkar Gud, og de skal helga dykk og vera heilage; for eg er heilag; de skal ikkje sulka dykk sjølve med noko av det kreket som krabbar på marki.',
        45: 'Kom i hug: Eg er Herren, som førde dykk ut or Egyptarlandet og vil vera dykkar Gud, og de skal vera heilage; for eg er heilag.',
        46: 'Dette er lovi um dyri og fuglarne og alt det livande som leikar i vatnet, og alle dei kvikjende som yrer på jordi,',
        47: 'so de kann skilja det reine frå det ureine, og dei dyri som kann etast frå deim, som ikkje må etast.»»',
    },
    12: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Tala til Israels-borni og seg: «Når ei kvende kjem i barnseng og fær ein son, so skal ho vera urein i sju dagar, likso lenge som når ho hev månadstidi si.',
        3: 'Den åttande dagen skal huveholdet umskjerast på sonen.',
        4: 'Sidan skal ho halda seg heime i tri og tretti dagar, medan blodet gjeng og ho reinskast; ikkje må ho røra noko heilagt, og ikkje må ho koma til heilagdomen fyrr reinskingsdagarne hennar er lidne.',
        5: 'Fær ho eit møybarn, so vert ho vera urein i tvo vikor, som når ho hev sine eigne tider, og sidan skal ho halda seg heime i seks og seksti dagar, medan blodet gjeng og ho reinskast.',
        6: 'Når reinskingstidi er ute, anten ho hev fenge son eller dotter, so skal ho koma med eit årsgamalt lamb til brennoffer og ein duveunge eller ei turtelduva til syndoffer; det skal ho bera fram åt møtetjelddøri, og gjeva det til presten,',
        7: 'og presten skal ofra det for Herrens åsyn, og gjera soning for henne, so ho vert rein etter blødingi. Denne lovi gjeld for alle kvende som hev fenge barn, anten det er son eller dotter.',
        8: 'Men den sim ikkje hev råd til å ofra eit lamb, skal ho taka tvo turtelduvor eller tvo duveungar, den eine til brennoffer og den andre til syndoffer, og presten skal gjera soning for henne; då vert ho rein att.»»',
    },
    13: {
        1: 'Og Herren tala atter til Moses og Aron, og sagde:',
        2: '«Når nokon fær notror eller utbrot eller ein ljos flekk på hudi, og det synest laga seg til spillsykja på likamen hans, so skal dei koma til Aron, øvstepresten, med honom, eller til ein av dei hine prestarne, Arons-sønerne.',
        3: 'Presten skal skoda dei såre flekkjerne på hudi, og dersom det synest liggja djupare enn skinnet, og håri på dei hev kvitna, so er det spillsykja, og med same presten ser det, skal han segja mannen urein.',
        4: 'Er det ein kvit sårkeflekk han hev fenge på hudi, og flekken ikkje synest liggja djupare enn skinnet, og håri på honom ikkje hev kvitna, so skal presten halda den sjuke innestengd i sju dagar.',
        5: 'Den sjuande dagen skal han sjå honom yver; tykkjer han då at sårken hev stana og ikkje breidt seg vidare ut yver hudi, so skal han halda mannen innestengd i sju dagar til.',
        6: 'Når dei er lidne, skal presten sjå honom yver ein gong til, og dersom den såre flekken hev vorte dim, og ikkje hev ete um seg på hudi, so skal han segja mannen rein; for då er det berre eit meinlaust utbrot; han skal två klædi sine, so er han rein.',
        7: 'Men et utbrotet meir og meir um seg på hudi hans etter han synte seg fram for presten og bad at han vilde segja honom rein -',
        8: 'ser presten, når den sjuke synar seg fram for honom andre venda, at utbrotet på hudi hev auka, so skal han segja honom urein; for då er det spillsykja.',
        9: 'Når ein hev fenge spillsykja, so skal dei koma til presten med honom.',
        10: 'Ser då presten kvite notror på hudi, som håri hev kvitna på, og som det gror villkjøt i,',
        11: 'So er det gamall spillsykja i hudi på likamen hans, og då skal presten segja honom urein; han treng ikkje fyrst stengja honom inne; for han er alt urein.',
        12: 'Bryt spillsykja ut so sterk at ho dekkjer heile hudi, frå hovud til fot, på den som er sjuk, kvar so presten fester augo sine -',
        13: 'ser presten, når han skodar den sjuke, at spillsykja hev breidt seg ut yver heile likamen hans, so skal han segja honom rein; er han heiltupp kvit vorten, so er han rein.',
        14: 'Men so snøgt det syner seg villkjøt på honom, er han urein,',
        15: 'og når presten ser villkjøtet, skal han segja honom urein; for villkjøtet er ureint; det er spillsykja i det.',
        16: 'Gjeng villkjøtet burt att, og den sjuke vert kvit, so skal han koma til presten,',
        17: 'og når presten hev skoda honom, og set at han hev vorte kvit, so skal han segja honom rein; for då er han rein.',
        18: 'Fær nokon ein verk, og den vert lækt,',
        19: 'men det sidan kjem ei kvit notra eller ein bleikraud flekk der verken hev vore, so skal han syna seg fram for presten.',
        20: 'Presten skal sjå honom yver, og dersom flekken synest vera lågare enn skinnet, og håri på honom hev kvitna, so skal han segja mannen urein; for då hev det vore spillsykja som braut ut i verken.',
        21: 'Men ser presten at det ikkje er kvite hår på flekken, og at han ikkje er lågare enn skinnet, og at han hev vorte dim, so skal han halda mannen innestengt i sju dagar.',
        22: 'Et so flekken vidare og vidare um seg på hudi hans, so skal presten segja honom urein; då er det sjukdom.',
        23: 'Men held flekken seg på same staden og ikkje et seg utyver, so er det berre æret etter verken, og då skal presten segja honom rein.',
        24: 'Hev nokon fenge eit brunesår på hudi, og kjøtet som gror i såret ter seg som ein bleikraud eller kvit flekk,',
        25: 'so skal presten skoda såret. Synest då flekken liggja djupare enn skinnet, og hev håri på honom kvitna, so er det spillsykja som hev brote ut i brunesåret, og presten skal segja mannen urein; det er spillsykja, det er’kje til å taka mist av.',
        26: 'Men ser presten, når han skodar flekken, at det ikkje er kvite hår på honom, og at han ikkje er lågare enn skinnet, og at han er dim, so skal han stengja mannen inne i sju dagar.',
        27: 'Den sjuande dagen skal han sjå honom yver, og dersom flekken hev ete um seg på skinnet hans, so skal presten segja honom urein; då er det spillsykja.',
        28: 'Men er flekken dim og hev halde seg på same staden og ikkje ete seg utyver, so er det merke etter brunesåret, og presten skal segja mannen rein; for dette er berre æret etter brunesåret.',
        29: 'Fær mann eller kvende ein sårkeflekk på hovudet eller i skjegget,',
        30: 'so skal presten skoda flekken, og dersom flekken synest liggja djupare enn skinnet, og det er tunne, grågule hår på honom, so skal presten segja det menneskjet ureint; då er det skurv, hår- eller skjeggsjuka.',
        31: 'Tykkjer presten som skodar sårkeflekken, at han ikkje ligg djupare enn skinnet, men der ikkje er svarte hår å sjå, so skal han halda den skurvute innestengd i sju dagar.',
        32: 'Den sjuande dagen skal han skoda den såre flekken, og dersom skurvet ikkje hev ete seg utyver, og det ikkje hev kome grågule hår på det, og det ikkje synest liggja djupare enn skinnet,',
        33: 'so skal den skurvute raka seg, men ikkje på skurveflekken, og presten skal halda honom innestengd i sju dagar til.',
        34: 'Når då presten den sjuande dagen skodar sårkeflekken endå ein gong, og skurvet ikkje hev ete um seg, og ikkje synest liggja djupare enn skinnet, so skal han segja den sjuke rein; han skal två klædi sine, so er han rein.',
        35: 'Er det likt til at skurvet vil eta um seg på hudi, etter den sjuke var sagd rein,',
        36: 'so skal presten sjå på honom, og ser han at skurvet hev breidt seg ut på skinnet hans, so treng han ikkje leita etter dei grågule håri; mannen er urein kor som er.',
        37: 'Men synest det for hans augo som skurvet hev stana, og hev det grott svarte hår på skurveflekken, so er sjukdomen lækt; den skurvute er rein att, og presten skal segja honom rein.',
        38: 'Fær mann eller kvende mange kvite flekkjer på likamen,',
        39: 'so skal presten sjå deim yver. Ser han då dimme, kvite flekker på skinnet deira, so er det bohak, som hev brote ut på deim, og dei er like reine for det.',
        40: 'Um ein misser håret, og vert snaud i hovudet, so er han like rein for det.',
        41: 'Fer håret av honom framantil, so han vert fleinskalla, so er han og like rein.',
        42: 'Men syner det seg bleikraude sårkeflekkjer der han er snaud, anten det er bak eller framme i hovudet, so er det spillsykja som bryt ut i nakken eller skallen hans.',
        43: 'Då skal presten skoda honom, og dersom han i nakken eller skallen hans finn bleikraude sårkenotror som likjest dei notrone ein spillsjuk kann hava på bulen,',
        44: 'so hev sjukdomen teke honom; han er urein, og presten skal med ein gong segja honom urein; han hev fenge sjuken i hovudet.',
        45: 'Den som spillsykja hev råma, lyt ganga med sundrivne klæde og uflitt hår; han skal sveipa eit plagg kring skjegget og ropa: «Urein, urein!»',
        46: 'Alt medan sjukdomen held honom, skal han gjelda for urein; for urein er han. For seg sjølv skal han bu; utanfor lægret skal han hava sitt tilhald.',
        47: 'Kjem det åtflekkjer på eit klædeplagg, ullplagg eller linplagg,',
        48: 'eller på ty som er vove eller bunde av lin- eller ullgarn, eller på ler eller noko som er gjort av ler,',
        49: 'og er flekkjerne som syner seg på klædeplagget eller på leret eller vevnaden eller bundingen, eller på noko som er gjort av ler, ljosgrøne eller raudvorne, so er det spillsykja, og det skal synast for presten.',
        50: 'Når presten hev skoda det, skal han halda det som flekkjerne er på, innelæst i sju dagar.',
        51: 'Ser han so den sjuande dagen at flekkjerne på klædeplagget eller vevnaden eller bundingen eller leret, kva det so leret er nytta til, hev ete seg vidare utyver, so er det stygg spillsykja i flekkjerne; det som dei hev synt seg på, er ureint,',
        52: 'og skal brennast upp, anten det er eit klædeplagg eller vevnad eller bunding av ull eller lin, eller noko som er gjort av ler; det fylgjer fårleg sott med det; di skal det brennast upp i elden.',
        53: 'Ser presten at flekkjerne på klædeplagget eller vevnaden eller bundingen eller leret ikkje hev ete um seg,',
        54: 'so skal han setja folk til å två det som flekkjerne hev synt seg på, og halda det innelæst sju dagar til.',
        55: 'Når han so skodar det etter det er tvege, og flekkjerne ikkje er annleis å sjå til enn fyrr, so er det ureint, endå skaden ikkje hev ete seg vidare utyver; det skal brennast upp i elden; for det er åt i det, på ranga eller på retta.',
        56: 'Men ser han at flekkjerne på plagget, eller på leret eller vevnaden eller bundingen, hev bleikna etter tvåtten, so skal han skjera deim ut.',
        57: 'Kjem dei att sidan, på klædeplagget eller vevnaden eller bundingen, eller på noko som er gjort av ler, so er det det vonde som bryt ut på nytt lag, og då skal ein brenna upp det som flekkjerne hev synt seg på.',
        58: 'Men dei klædi og det vovne og bundne tyet, og det leret som flekkjerne gjeng burt av når ein tvær det, det skal tvåast upp att, so er det reint.',
        59: 'Dette er lovi um åtflekkjer på ull- eller linklæde og vevnad og bunding, og allslags ting som er gjorde av ler, so de kann vita når sovore skal haldast for reint, og når det skal haldast for ureint.»',
    },
    14: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«So er dei fyresegnerne de skal fylgja når ein som hev havt spillsykja, skal reinsast: Han skal førast fram for presten;',
        3: 'og presten skal ganga utanfor lægret og sjå honom yver, og dersom han er lækt for sjukdomen,',
        4: 'so skal presten segja folk til å henta tvo livande reine fuglar og noko cedertre og karmesin og bergmynta til den som skal reinsast,',
        5: 'og lata deim slagta den eine fuglen uppyver eit leirfat som er fyllt med kjelde- eller bekkjevatn.',
        6: 'So skal han taka den livande fuglen og cedertreet og karmesinen og bergmynta, og duppa alt saman, den levande fuglen med, i blodet av den fuglen som er slagta yver kjeldevatnet,',
        7: 'og skvetta det sju vendor på den som skal reinsast etter spillsykja, og reinsa honom, og den livande fuglen skal han lata fljuga sin veg.',
        8: 'So skal den som vert reinsa två klædi sine, og raka av seg alt håret, og lauga seg, so vert han rein, og sidan kann han få koma inn i lægret; men han skal halda seg utanfor tjeldbudi si i sju dagar.',
        9: 'Den sjuande dagen skal han raka seg att; både hovudhåret og skjegget og augnebrunerne, alt håret sitt, skal han raka av seg; og han skal två klædi sine, og lauga likamen sin i vatn. Då er han rein.',
        10: 'Den attande dagen skal han taka tvo verlamb som ikkje hev lyte, og eit årsgamalt lytelaust saulamb, og til grjonoffer tri kannor fint mjøl som er blanda med olje, og so ein halvpott med olje.',
        11: 'Og presten som stend fyre reinsingi, skal føra den som vert reinsa og alle offergåvorne hans fram for Herrens åsyn i møtetjelddøri.',
        12: 'So skal presten taka det eine lambet og den halve potten med olje og bera fram til skuldoffer, og svinga det att og fram for Herrens åsyn.',
        13: 'Lambet skal dei slagta på same staden som dei slagtar syndofferet og brennofferet, på den heilage staden; for skuldofferet høyrer presten til liksom syndofferet; det er høgheilagt.',
        14: 'So skal presten taka noko av skuldofferblodet og strjuka på den høgre øyresnippen åt den som vert reinsa, og på den høgre tumarsfingeren og den høgre tumarståi hans;',
        15: 'og han skal taka noko av den halve potten olje og hella ut i den vinstre handi si,',
        16: 'og so duppa den høgre peikefingeren i oljen som han hev i vinstre handi, og skvetta med fingeren av oljen sju gonger for Herrens åsyn.',
        17: 'Noko av den oljen som er att i handi hans, skal han strjuka på den høgre øyresnippen åt den som vert reinsa, og på den høgre tumarsfingeren og den høgre tumarståi hans, yver skuldofferblodet.',
        18: 'Og det som endå er att i handi hans av oljen, skal han strjuka på hovudet åt den som vert reinsa. Soleis skal presten gjera soning for honom for Herrens åsyn.',
        19: 'So skal presten bera fram syndofferet, so den som vert reinsa kann få soning for det som var ureint ved honom, og sidan skal han slagta brennofferet.',
        20: 'Når då presten hev bore fram brennofferet og grjonofferet på altaret, og fullført soningi for honom, so er han rein att.',
        21: 'Men er det ein fatig mann som ikkje hev råd til so mykje, so skal han taka eit lamb til skuldoffer - det skal svingast att og fram til soning for honom - og ei kanna fint mjøl, blanda med olje, til grjonoffer, og ein halv pott med olje,',
        22: 'og so tvo turtelduvor eller duveungar, det som han hev råd til; den eine skal vera syndoffer, og den andre brennoffer.',
        23: 'Den åttande dagen etter han hev vorte rein, skal han bera offergåvorne fram for Herrens åsyn til møtetjelddøri, og gjeva deim til presten.',
        24: 'Og presten skal taka skuldofferlambet og oljen og svinga det att og fram for Herrens åsyn.',
        25: 'Når skuldofferlambet er slagta, skal presten taka noko av skuldofferblodet og strjuka på den høgre øyresnippen åt den som vert reinsa, og på den høgre tumarsfingeren og den høgre tumarståi hans.',
        26: 'So skal han hella noko av oljen ut i den vinstre handi si',
        27: 'og med den høgre peikefingeren skvetta sju vendor for Herrens åsyn av oljen som han hev i vinstre handi.',
        28: 'Noko av den oljen som presten hev i vinstre handi, skal han strjuka på den høgre øyresnippen åt den som vert reinsa, og på den høgre tumarsfingeren og den høgre tumarståi hans, yver skuldofferblodet,',
        29: 'og det som endå er att av oljen som presten hev i handi, skal han strjuka på hovudet åt den som vert reinsa, so han kann finna nåde hjå Herren.',
        30: 'So skal han bera fram turtelduvorne eller duveungarne, det som han hadde råd til å gjeva,',
        31: 'den eine til syndoffer og den andre til brennoffer, og i hop med deim grjonofferet. Soleis skal presten gjera soning framfor Herrens åsyn for den som skal reinsast.',
        32: 'Dette er dei fyresegnerne de skal fylgja når ein som hev liti råd, skal reinsast etter spillsykja.»',
        33: 'Og Herren tala atter til Moses, og sagde:',
        34: '«Når de kjem inn i Kana’ans-landet, som eg gjev dykk til eiga, og eg let det koma spillsykja på noko av husi i landet dykkar,',
        35: 'so skal huseigaren koma og segja frå til presten, at det hev synt seg flekkjer som likjest spillsykja på huset hans.',
        36: 'Då skal presten setja deim til å rydja utor huset innan han kjem og skodar skaden, so ikkje alt som er der, skal verta ureint, og so skal han koma og skoda huset.',
        37: 'Ser han då at flekkjerne på husveggjerne ter seg som grøngule eller raudvorne sukkor, og synest liggja djupare enn veggflata,',
        38: 'so skal han ganga til døri og ut or huset, og halda det læst i sju dagar.',
        39: 'Den sjuande dagen skal presten koma att og sjå etter, og ser han då at skaden hev ete um seg på husveggjerne,',
        40: 'so skal han setja folk til å brjota ut dei steinarne som flekkjerne hev synt seg på, og kasta deim på ein urein stad utanfor byen.',
        41: 'Dei skal skrapa huset innantil, rundt ikring, og leiret som dei hev skrapa av, skal dei og føra burt og kasta på ein urein stad utanfor byen.',
        42: 'Og so skal dei taka andre steinar og setja inn i staden for dei gamle, og nytt leir skal dei taka og klina huset med.',
        43: 'Bryt det vonde ut att på huset, etter steinarne er uttekne, og huset er skrapa og klint,',
        44: 'so skal presten koma og sjå etter, og ser han då at skaden hev ete um seg, so er det stygg spillsykja på huset; det er ureint,',
        45: 'og dei skal riva det ned, både steinarne og timberet og alt leiret, og føra det ut or byen, til ein urein stad.',
        46: 'Den som gjeng inn i huset dei dagarne det er attlæst, han vert urein alt til kvelds.',
        47: 'Den som hev lege i huset, skal två klædi sine, og det same skal den som hev ete der.',
        48: 'Ser presten, når han kjem og skodar huset, at dei stygge flekkjerne ikkje hev ete um seg etter det vart klint, so skal han segja huset reint; for då er det vonde burte.',
        49: 'So skal han til syndoffer for huset taka tvo fuglar og noko cedertre og karmesin og bergmynta.',
        50: 'Den eine fuglen skal han slagta yver eit leirfat som er fyllt med kjelde- eller bekkjevatn,',
        51: 'og so skal han taka cedertreet og bergmynta og karmesinen og den livande fuglen, og duppa det i blodet av den fuglen som er slagta, og i kjeldevatnet, og skvetta på huset sju vendor.',
        52: 'Når han då hev reinsa huset for synd med fugleblodet og kjeldevatnet og den livande fuglen og cedertreet og bergmynta og karmesinen,',
        53: 'so skal han sleppa den livande fuglen ut or byen og lata honom fljuga. Soleis skal han gjera soning for huset, so det vert reint.',
        54: 'So er fyresegnerne um allslags spillsykja, og um skurv,',
        55: 'og um åtflekkjer på klæde og hus,',
        56: 'og um notror og utbrot og ljose flekkjer på hudi,',
        57: 'so de kann vita når noko er ureint, og når det er reint.» Dette var lovi um spillsykja.',
    },
    15: {
        1: 'Og Herren tala atter til Moses og Aron, og sagde:',
        2: '«Tala til Israels-borni og seg til deim: «Når ein mann hev sådflod, so er han urein.',
        3: 'So lenge flodi varer, fylgjer det ureinskap med honom, og det anten likamen gjev væta frå seg jamt eller stundom held henne inne; i båe høve er han urein.',
        4: 'Kvar lega han ligg på og kvar sess han sit på, vert urein.',
        5: 'Den som kjem nær lega hans, lyt två klædi sine og lauga seg, og er urein alt til kvelds.',
        6: 'Og den som set seg på noko han hev sete på, lyt og två klædi sine og lauga seg, og er urein alt til kvelds.',
        7: 'Like eins den som kjem nær den sjuke sjølv; han lyt två klædi sine og lauga seg, og er urein alt til kvelds.',
        8: 'Kjem den sjuke til å sputta på ein som er rein, so lyt den han hev sputta på två klædi sine og lauga seg, og er urein alt til kvelds.',
        9: 'Kvar sal og kvart vognsæte som den sjuke sit på, vert ureint.',
        10: 'Den som kjem nær noko av det han hev under seg, vert urein alt til kvelds, og den som ber det burt, lyt två klædi sine og lauga seg, og er urein alt til kvelds.',
        11: 'Tek den sjuke burtpå nokon, og ikkje fyrst hev skylt henderne sine i vatn, so lyt den han hev teke burtpå två klædi sine og lauga seg, og er urein alt til kvelds.',
        12: 'Kjem den sjuke nær eit leirfat, so skal det slåast sund; men er det eit trefat, so skal det skyljast i vatn.',
        13: 'Når den sjuke hev kome seg av flodi, skal han telja sju dagar fram frå di han vart god att; då skal han två klædi sine, og lauga likamen sin i kjelde- eller bekkjevatn, so er han rein.',
        14: 'Den åttande dagen skal han taka tvo turtelduvor eller tvo duveungar, og ganga fram i møtetjelddøri for Herrens åsyn, og gjeva deim til presten,',
        15: 'og presten skal ofra deim, den eine til syndoffer, og den andre til brennoffer. Soleis skal presten gjera soning for honom for Herrens åsyn, so han vert rein att etter sjukdomen.',
        16: 'Når det gjeng såd frå ein mann i svevne, so skal han lauga heile likamen sin i vatn, og han er urein alt til kvelds.',
        17: 'Og alle klæde eller skinnplagg som sådet hev kome på, lyt tvåast vel, og er ureine alt til kvelds.',
        18: 'Ligg ein mann hjå eit kvende, og det gjeng såd frå honom, so lyt dei båe lauga seg, og vera ureine alt til kvelds.',
        19: 'Når eit kvende hev månadstidi si, og det gjeng blod frå henne, so er ho urein i sju dagar, og den som kjem nær henne, er urein alt til kvelds.',
        20: 'Alt ho ligg eller sit på medan ho hev det soleis, vert ureint.',
        21: 'Den som kjem nær lega hennar, lyt två klædi sine og lauga seg, og er urein alt til kvelds.',
        22: 'Og den som kjem nær noko av det ho hev sete på, lyt og två klædi sine og lauga seg, og er urein alt til kvelds.',
        23: 'Ligg det eitkvart i sengi eller i sessen hennar, og nokon kjem nær det, so er han urein alt til kvelds.',
        24: 'Og dersom ein mann ligg med henne, og det kjem blod på honom, so vert han og urein i sju dagar, og alt det han ligg på, vert ureint.',
        25: 'Når det gjeng blod frå eit kvende i mange dagar på ei tid som ho ikkje hev månadssjuken sin, eller når blodet gjeng frå henne lenger enn vanleg i månadstidi, so er ho urein so lenge denne ureine flodi varer, liksom når ho hev månadssjuken.',
        26: 'Um alt det ho ligg på medan ho hev blodflod, gjeld det same som er sagt um lega hennar det bil ho hev månadssjuken, og alt ho sit på, vert ureint, som når ho hev månadssjuken.',
        27: 'Den som kjem nær det, vert urein; han lyt två klædi sine og lauga seg, og er urein alt til kvelds.',
        28: 'Vert ho god att av blodflodi, so skal ho telja sju dagar fram; so er ho rein.',
        29: 'Og den åttande dagen skal ho taka tvo turtelduvor eller tvo duveungar og bera åt møtetjelddøri, til presten,',
        30: 'og presten skal ofra deim, den eine til syndoffer, og den andre til brennoffer. Soleis skal presten gjera soning for henne for Herrens åsyn, so ho vert rein att etter sjukdomen.',
        31: 'De skal vara Israels-borni for det som kann gjera deim ureine, so dei ikkje skal sulka bustaden min, som eg hev reist millom deim, og lata livet for ureinska si.',
        32: 'Dette er lovi um deim som hev flod: um menner som det gjeng såd frå, so dei vert ureine,',
        33: 'og um kvende som hev månadstidi si, og um folk som er flodsjuke, både menner og kvende, og um menner som ligg med ureine kvende.»»',
    },
    16: {
        1: 'Då dei tvo Arons-sønerne var slokna, dei som laut døy for di dei gjekk fram for Herrens åsyn, då tala Herren til Moses,',
        2: 'og sagde til honom: «Seg med Aron, bror din, at han ikkje må ganga inn i heilagdomen, innanfor forhenget og fram åt kista med kerubarne, kva tid han vil; då kunde han missa livet; for uppyver kerubarne syner eg meg i skyi.',
        3: 'Soleis lyt Aron vera budd når han skal ganga inn i heilagdomen: Han skal hava med seg ein ung ukse til syndoffer og ein ver til brennoffer.',
        4: 'Og han skal klæda seg i ein vigd linkjole, og hava ei linbrok på seg næst kroppen, og binda eit linbelte kring livet, og sveipa eit linplagg kring hovudet; vigde klæde lyt det vera, og fyrr han tek deim på seg, skal han lauga likamen sin i vatn.',
        5: 'Og av Israels-lyden skal han få tvo geitebukkar til syndoffer og ein ver til brennoffer.',
        6: 'So skal Aron leida fram syndofferuksen sin, og beda for seg og huset sitt.',
        7: 'Og han skal taka båe bukkarne, og leida deim fram for Herrens åsyn i møtetjelddøri.',
        8: 'Og han skal draga strå um bukkarne, eit for Herren og eit for Azazel.',
        9: 'Og den bukken som fell på Herrens lut, skal han leida fram og ofra til syndoffer.',
        10: 'Men den som fell på Azazels lut, skal leidast livande fram for Herrens åsyn, og dei skal lesa bøner yver honom, og senda honom ut i øydemarki til Azazel.',
        11: 'Når Aron hev leidt fram syndofferuksen sin, og bede for seg og huset sitt, so skal han fyrst slagta uksen,',
        12: 'og so skal han fylla glodfatet sitt med gløder frå altaret der elden brenn for Herrens åsyn, og taka tvo nevar med finstøytt, angande røykjelse og bera innanfor forhenget,',
        13: 'og han skal leggja røykjelsen på elden for Herrens åsyn, so røyken gøymer lovtavlekista med kerubarne; elles lyt han døy.',
        14: 'So skal han taka noko av ukseblodet og skvetta med fingeren fremst på kisteloket mot aust, og framanfor kista skal han skvetta med fingeren av blodet sju gonger.',
        15: 'So skal han slagta den bukken som er etla til syndoffer for folket, og bera blodet innanfor forhenget, og gjera med det som han gjorde med blodet av uksen: skvetta det på kisteloket og framanfor kista.',
        16: 'Soleis skal han gjera soning for heilagdomen, og reinsa honom for dei broti som Israels-borni hev sulka honom med kvar gong dei hev synda, og det same skal han gjera med heile møtetjeldet, som er reist millom deim, midt i ureinskalpen deira.',
        17: 'Og det må ikkje finnast noko menneskje i møtetjeldet frå Aron gjeng inn og skal halda bøn i heilagdomen, og til han kjem ut att og hev gjort soning for seg og for huset sitt og for heile Israels-lyden.',
        18: 'So skal han ganga ut til altaret, som er reist for Herrens åsyn, og gjera soning for det: Han skal taka noko av ukseblodet og noko av bukkeblodet og strjuka rundt ikring på altarhorni,',
        19: 'og skvetta med fingeren av blodet på altaret sju gonger, og reinsa det for den sauren som Israels-borni hev sulka det med, og helga det.',
        20: 'Når Aron hev fullført soningi for heilagdomen og møtetjeldet og altaret, so skal han leida fram den livande bukken,',
        21: 'og leggja henderne på hovudet hans, og skrifta uppyver honom alle dei brot og misgjerningar Israels-folket hev gjort so ofte dei hev synda, og leggja deim på hovudet åt bukken, og so senda honom ut i øydemarki med ein mann som stend reidug.',
        22: 'Og bukken skal bera alle broti deira med seg til eit land som ligg langt, langt av leid. Når Aron hev sendt bukken ut i øydemarki,',
        23: 'skal han ganga inn i møtetjeldet, og taka av seg linklædi som han hadde på seg då han gjekk inn i heilagdomen, og gøyma deim der.',
        24: 'So skal han lauga likamen sin i vatn på ein heilag stad, og klæda seg i den vanlege bunaden sin, og so ganga ut att, og ofra brennofferet sitt og brennofferet for folket, og gjera soning for seg og for deim.',
        25: 'Og feittet av syndofferet skal han brenna på altaret, so røyken stig upp mot himmelen.',
        26: 'Den som hev leidt bukken burt til Azazel, lyt två klædi sine og lauga likamen sin i vatn; då fyrst kann han få koma inn i lægret.',
        27: 'Uksen og bukken som vart slagta til syndoffer, og som dei tok blodet av og bar inn i heilagdomen til soning, skal dei føra ut or lægret, og brenna både skinni og kjøtet og møki.',
        28: 'Den som brenner det, lyt två klædi sine og lauga likamen sin i vatn; sidan kann han koma inn i lægret.',
        29: 'Og dette skal vera ei æveleg lov hjå dykk: Den tiande dagen i den sjuande månaden skal de fasta og ikkje gjera noko slag arbeid, korkje den som er fødd og boren i landet, eller den framande som held til hjå dykk.',
        30: 'For den dagen skal dei gjera soning for dykk, og reinsa dykk for alle synderne dykkar, so de vert reine for Herren.',
        31: 'Ei høgtidshelg skal det vera for dykk, og då skal de fasta; det skal vera ei æveleg lov.',
        32: 'Den som skal standa for soningi, er presten, han som hev vorte salva og sett til å styra preste-embættet etter far sin. Han skal klæda seg i dei heilage linklædi,',
        33: 'og gjera soning for det høgheilage romet og møtetjeldet og altaret; og prestarne og heila ålmugen skal han og gjera soning for.',
        34: 'Det skal vera ei æveleg lov hjå dykk, at dei ein gong um året skal gjera soning for Israels-borni og reinsa deim for alle synderne deira.» Og Aron gjorde som Herren hadde sagt til Moses.',
    },
    17: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Tala til Aron og sønerne hans og til heile Israels-folket, og seg med deim: «Høyr no kva Herren vil de skal gjera:',
        3: 'Er det nokon mann av Israels-ætti som slagtar ein ukse eller ein sau eller ei geit anten i eller utanfor lægret,',
        4: 'og ikkje leider deim fram til møtetjelddøri og ofrar Herren ei gåva framfor bustaden hans, so skal den mannen reknast jamgod med ein dråpsmann; han hev rent ut blod og skal rydjast ut or folket sitt.',
        5: 'Difor skal Israels-borni koma til Herren med slagtofferi sine som dei er vane å slagta ute på marki, og leida deim fram åt møtetjelddøri, til presten, og slagta deim til takkoffer åt Herren.',
        6: 'Og presten skal sprøyta blodet yver Herrens altar som stend framanfor møtetjelddøri, og brenna feittet til godange for Herren.',
        7: 'Og dei skal ikkje lenger gjeva offeri sine til dei raggute trolli som dei flyg etter. Dette skal vera ei æveleg lov for deim og etterkomarane deira.»',
        8: 'Og dette skal du segja med deim: «Dersom nokon av Israels-ætti, eller av dei framande som bur millom deim, ber fram eit brennoffer eller slagtoffer,',
        9: 'og ikkje kjem til møtetjelddøri med det og ofrar det til Herren, so skal den mannen rydjast ut or folket sitt.',
        10: 'Og dersom nokon av Israels-ætti, eller av dei framande som bur millom deim, et aldri so lite blod, so skal eg kvessa augo imot den mannen, og rydja honom ut or folket hans.',
        11: 'For livet i likamen ligg i blodet, og eg hev gjeve dykk lov til å hava blod på altaret til soning for livet dykkar. For blodet det sonar av di livet ligg i det.',
        12: 'Difor segjer eg til Israels-borni: Ingen av dykk må eta blod; dei framande som bur hjå dykk, må heller ikkje gjera det.',
        13: 'Og når nokon av Israels-borni, eller av dei framande som bur millom deim, veider villdyr eller fuglar som dei hev lov til å eta, so skal han lata blodet renna ut på marki og hava jord yver det.',
        14: 'For livet i likamen, det er blodet med livet som ligg i det; difor hev eg sagt til Israels-folket: De må ikkje eta blodet av noko kvikjende! For livet i kvart kvikjende, det er blodet som er i det; kven som et det, han skal rydjast ut.',
        15: 'Hev nokon mann, anten han er fødd i landet eller han er framand, ete av eit dyr som er sjølvdaudt eller ihelrive, so skal han två klædi sine og lauga seg, og er urein alt til kvelds; sidan er han rein.',
        16: 'Tvær han ikkje klædi sine og ikkje laugar likamen sin, so gjer han ei synd som han lyt lida for.»»',
    },
    18: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Tala til Israels-folket, og seg med deim: «Eg er Herren, dykkar Gud.',
        3: 'De skal ikkje fara etter det som er skikk og sed i Egyptarlandet, der de fyrr budde, eller i Kana’ans-landet, som eg fører dykk til, og ikkje fylgja loverne deira.',
        4: 'Mine bod skal de lyda, og mine lover skal de halda dykk etter og fylgja. Eg er Herren, dykkar Gud;',
        5: 'de skal halda bodi og loverne mine; held menneskja deim, so skal ho finna livet i deim. Kom i hug: eg er Herren.',
        6: 'Ingen av dykk må koma innåt noko nærskyldt kvende og søkja seng med henne; kom i hug: eg er Herren.',
        7: 'Du skal hava age for lega åt far din og mor di. Ho er mor di; du skal ikkje søkja seng med henne.',
        8: 'Du skal ikkje søkja seng med stykmor di; ho er vivet åt far din.',
        9: 'Du skal ikkje søkja seng med syster di, som hev same far eller same mor som du; anten ho er fødd i eller utanfor huset, so skal du ikkje søkja seng med henne.',
        10: 'Du skal ikkje søkja seng med sonedotter eller dotterdotter di; for det er ditt eige avkjøme.',
        11: 'Du skal ikkje søkja seng med dotter åt stykmor di; ho er dotter åt far din, og ho er syster di.',
        12: 'Du skal ikkje søkja seng med farsyster di; det er same blodet som far din.',
        13: 'Du skal ikkje søkja seng med morsyster di; det er same blodet som mor di.',
        14: 'Du skal ikkje skjemma lega åt farbror din og koma kona hans for nær; for ho er farsyster di.',
        15: 'Du skal ikkje søkja seng med verdotter di. Ho er vivet åt son din; du skal ikkje søkja seng med henne.',
        16: 'Du skal ikkje søkja seng med brorkona di; ho er vivet åt din eigen bror.',
        17: 'Hev du havt samlega med et kvende, so skal du ikkje søkja seng med dotter hennar; heller ikkje skal du ganga i seng med sonedotter eller dotterdotter hennar. Det er blodskam; for dei er same folket.',
        18: 'Du skal ikkje gifta deg med versyster di og søkja seng med henne, medan kona di liver; for då set du hat millom deim.',
        19: 'Du skal ikkje koma innåt noko kvende og søkja seng med henne, medan ho hev månadssjuken sin og er urein.',
        20: 'Du skal ikkje liggja hjå kona åt grannen din og på den måten gjera deg urein.',
        21: 'Du skal ikkje gjeva noko av borni dine frå deg til Molok; for då vanhelgar du namnet åt din Gud. Eg er Herren!',
        22: 'Du skal ikkje liggja hjå ein kar, som ein ligg med eit kvende; det er ein styggedom.',
        23: 'Med dyr må du aldri blanda deg; for då vert du urein. Og heller ikkje må kvende gjeva seg i lag med dyr og para seg med deim. Det er skjemdarferd.',
        24: 'Gjer dykk ikkje ureine med sovori åtferd! For slikt var det dei gjorde seg ureine med, dei folki som eg driv ut for augo dykkar;',
        25: 'då vart landet ureint, og eg heimsøkte det for broti deira, og landet støytte deim ut.',
        26: 'Men de skal halda bodi og loverne mine, både de sjølve og dei framande som bur millom dykk; de skal ikkje gjera noko av dei skjemdarverki',
        27: 'som dei sulka ut landet med, dei som åtte det fyre dykk;',
        28: 'for då kjem landet til å støyta dykk ut, for di de sulkar det til, liksom det støytte ut det folket som var der fyre dykk.',
        29: 'For alle dei som gjer slike skjemdarverk, dei skal rydjast ut or folket sitt.',
        30: 'So haldt då dei bodi eg hev gjeve dykk, og tak ikkje etter dei fæle ugjerderne som dei hadde, dei som var fyre dykk; for med det gjer de dykk ureine: Kom i hug: eg er Herren, dykkar Gud!»»',
    },
    19: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Tala til heile Israels-lyden, og seg til deim: «De skal vera heilage; for eg, Herren, dykkar Gud, er heilag.',
        3: 'De skal hava age for mor og far, og halda helgarne mine. Kom i hug: eg er Herren, dykkar Gud!',
        4: 'De skal ikkje venda dykk til avgudarne, og ikkje gjera dykk støypte gudar! Eg, Herren, er dykkar Gud.',
        5: 'Når de ofrar eit takkoffer til Herren, skal de gjera det soleis at han kann hava hugnad av dykk.',
        6: 'De skal eta kjøtet same dagen som de ofrar, eller og dagen etter; men det som er att tridje dagen, skal de kasta på elden.',
        7: 'Den tridje dagen skal det haldast for utskjemt og ureint; et nokon av det då, so hev Herren ingen hugnad i offeret,',
        8: 'og den som et av det, gjer ei synd som han lyt lida for: han vanhelgar det som er vigt åt Herren, og han skal rydjast ut or folket sitt.',
        9: 'Når de haustar kornet av åkrarne dykkar, so skal du ikkje skjera for vel utåt reini, og det som vert liggjande att etter skurden, skal du ikkje plukka upp.',
        10: 'Heller ikkje skal du sanka dei bæri som er att på trei etter du hev hausta vinhagen din, eller henta upp deim som er neddotne. Deim skal du lata vera att til dei fatige og framande. Kom i hug: eg er Herren, dykkar Gud.',
        11: 'De skal ikkje stela, og de skal ikkje dylja burt det som de hev i varveitsla, og de skal ikkje svika kvarandre.',
        12: 'De skal ikkje sverja på lygn i namnet mitt; for då vanhelgar de namnet åt dykkar Gud. Kom i hug: eg er Herren.',
        13: 'Du skal ikkje gjera urett mot grannen din, og ikkje rana ifrå honom. Det ein dagarbeidar skal hava i løn, må ikkje verta liggjande hjå deg natti yver.',
        14: 'Du skal ikkje banna den som dauv er, og ikkje leggja mein i vegen for den som er blind. Du skal hava age for din Gud; eg er Herren!',
        15: 'De skal ikkje gjera urett mot nokon på tinget; ikkje skal du halda med ein mann for di han er fatig, og ikkje skal du snilda på saki hans for di han er rik; rettferdigt skal du døma landsmannen din.',
        16: 'Du skal ikkje ganga ikring og baktala folk. Du skal ikkje leggja deg ut um å få grannen din dømd frå livet. Kom i hug: eg er Herren!',
        17: 'Du skal ikkje bera hat til bror din i hjarta; men du må vel tala honom til rettes, so du ikkje skal bera synd for hans skuld.',
        18: 'Du skal ikkje hemna deg og ikkje bera agg til nokon av landsfolket ditt, men du skal vilja grannen din likso vel som deg sjølv. Kom i hug: eg er Herren.',
        19: 'De skal halda loverne mine! Du skal ikkje lata tvo dyr av ulikt slag para seg. Du skal ikkje så åkeren din med tvo ulike kornslag. Du skal ikkje ganga med klæde som er vovne av tvo ulike garnslag.',
        20: 'Når ei kvinna er i tenesta hjå ei mann som ho er trulova med, men ikkje er utløyst eller frigjevi, og so ein annan mann ligg med henne og skjemmer henne, so skal ein fylgja deim med retten, men dei skal ikkje straffast på livet, etter di ho ikkje var fri kvinna.',
        21: 'Han skal til bot for brotet sitt koma til møtetjelddøri med ein ver, som skal vera skuldoffer åt Herren,',
        22: 'og når presten hev gjort soning for honom hjå Herren med skuldofferveren, skal han få tilgjeving for den syndi han hev gjort.',
        23: 'Når de kjem åt landet dykkar, og plantar allslags frukttre, so skal de halda den fyrste frukti dei ber for urein; tri år skal trei vera ureine for dykk, og de må ikkje eta frukti deira.',
        24: 'Det fjorde året skal all frukti vigjast åt Herren med ei takkehøgtid.',
        25: 'Fyrst i det femte året må de eta frukti deira, so skal dei bera so mykje meir åt dykk sidan. Kom i hug: eg er Herren, dykkar Gud!',
        26: 'De må ikkje eta noko med blodet i. De skal ikkje fara med spådoms- eller trollkunster.',
        27: 'De skal ikkje rundklyppa håret dykkar, og ikkje stytta skjegget.',
        28: 'De skal ikkje skjera dykk i holdet av sorg yver ein som er avliden, og ikkje brenna inn bokstaver eller bilæte på likamen dykkar. Kom i hug: eg er Herren!',
        29: 'Du skal ikkje vanhelga dotter di, og lata henne verta skjøkja, so folket vert usedugt og landet fullt av ulivnad.',
        30: 'De skal halda helgarne mine, og hava age for heilagdomen min. Eg er Herren.',
        31: 'Gakk ikkje til deim som manar fram draugar og spåvette! Lat deim ikkje spå dykk; for med de gjer de dykk ureine. Kom i hug: eg er Herren, dykkar Gud!',
        32: 'For dei grå håri skal du reisa deg og æra den som gamall er; du skal hava age for din Gud. Kom i hug: eg er Herren.',
        33: 'Når ein framand bur hjå deg og held til i landet dykkar, so skal de ikkje vera hard med honom;',
        34: 'han skal vera for dykk som ein av landsmennerne dine, og du skal vilja honom likso vel som deg sjølv; for de var og framande i Egyptarlandet. Kom i hug: eg er Herren, dykkar Gud!',
        35: 'De skal ingen urett gjera, korkje på ting eller torg; rett famn og rett aln,',
        36: 'rett vegt og rette lodd, rett skjeppa og rett kanna skal de bruka. Eg er Herren, dykkar Gud, som fylgde dykk ut or Egyptarlandet.',
        37: 'Agta vel på alle loverne og retterne mine, og liv etter deim! Kom i hug: eg er Herren!»»',
    },
    20: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Seg til Israels-folket: «Hender det at nokon av Israels-mennerne, eller av dei framande som held til i Israel, gjev noko av borni sine frå seg til Molok, so skal han lata livet: landslyden skal steina honom i hel.',
        3: 'Og eg vil kvessa augo mot den mannen, og rydja honom ut or folket hans, for di han hev gjeve Molok barnet sitt og sulka heilagdomen min og vanhelga mitt heilage namn:',
        4: 'um landslyden let att augo og ikkje læst sjå at han gjev barnet sitt til Molok, og ikkje drep honom,',
        5: 'so vil eg kvessa augo mot honom og mot ætti hans, og rydja honom ut or folket hans, både honom og alle deim som fylgjer i fotfaret hans, og held seg med Molok.',
        6: 'Gjeng nokon til deim som manar fram draugar og spåvette, og held seg med deim, so vil eg kvessa augo mot honom og rydja honom ut or folket hans.',
        7: 'De skal helga dykk og vera heilage; for eg, Herren, er dykkar Gud.',
        8: 'Agta vel på loverne mine, og liv etter deim! Kom i hug: eg er Herren, som helgar dykk!',
        9: 'Den som bannar far sin og mor si, han skal lata livet. Han hev banna far og mor: blodet hans kjem på honom sjølv.',
        10: 'Den som held seg med ei gift kona, med kona åt grannen sin, han skal lata livet, både han og den kona han hev halde seg med.',
        11: 'Ligg nokon med stykmor si, so skjemmer han æra åt far sin; dei skal båe lata livet, og blodet deira kjem på deim sjølve.',
        12: 'Ligg nokon hjå sonekona si, so skal dei båe lata livet. Dei hev gjort eit skjemdarverk, og blodet deira kjem på deim sjølve.',
        13: 'Ligg nokon hjå ein kar, som ein ligg hjå eit kvende, so gjer dei båe ei stygg gjerning; dei skal lata livet; blodet deira kjem på deim sjølve.',
        14: 'Tek nokon både mor og dotter til kona, so er det blodskam; dei skal brennast på bål, både han og dei; sovori sedløysa må ikkje finnast hjå dykk;',
        15: 'Blandar nokon seg med eit dyr, so skal han lata livet, og dyret skal de drepa.',
        16: 'Og held ei kvinna seg innåt eit dyr og parar seg med det, so skal de slå i hel både kvinna og dyret. Dei som gjer slikt, skal lata livet, og blodet deira kjem på deim sjølve.',
        17: 'Tek nokon syster si, som hev same far eller same mor som han, og søkjer seng med henne, og ho med honom, so er det blodskam, og dei skal rydjast ut for augo åt landslyden. Han hev søkt seng med syster si: han lyt lida for brotet sitt.',
        18: 'Ligg nokon med ei kvinna medan ho hev månadssjuken sin, og nækjer blygsli hennar, tek han dekkjet av kjelda hennar, og ho nækjer blodkjelda si, so skal dei båe rydjast ut or folket sitt.',
        19: 'Du skal ikkje søkja seng med morsyster eller farsyster di; den som det gjer, skjemmer si eigi ætt: dei lyt lida for brotet sitt.',
        20: 'Ligg nokon hjå kona åt farbror sin, so vanærar han farbror sin: dei lyt lida for syndi si, og skal døy barnlause.',
        21: 'Gifter nokon seg med brorkona si, so er det ei skam; han hev vanæra bror sin: dei skal ikkje få born.',
        22: 'So lyd då alle bodi og alle loverne mine, og liv etter deim, so landet ikkje skal støyta dykk ut att, det landet som eg fører dykk til og vil lata dykk bu i!',
        23: 'Far ikkje etter skikkarne åt det folket som eg jagar ut for dykkar skuld! Dei gjorde alt dette; då fekk eg stygg til deim,',
        24: 'og eg sagde til dykk: De skal få landet deira, eit land som fløymer med mjølk og honning; eg vil gjeva dykk det til eiga, eg, Herren, dykkar Gud, som hev skilt dykk ut frå alle andre folk.',
        25: 'Difor skal de skilja millom reine og ureine dyr og reine og ureine fuglar, og ikkje gjera dykk sjølve ufysne med å eta dei dyri eller fuglarne eller noko av det kreket som eg hev skilt ut, og sagt de skal halda for ureine.',
        26: 'De skal vera meg heilage; for eg, Herren, er heilag, og eg hev skilt dykk ut frå alle andre folkeslag, so de skal høyra meg til.',
        27: 'Er det nokon mann eller noko kvende som fer med å mana fram draugar eller spåvette, so skal dei lata livet: dei skal steinast i hel, og blodet deira kjem på deim sjølve.»»',
    },
    21: {
        1: 'Og Herren sagde til Moses: «Tala til prestarne, Arons-sønerne, og seg med deim: «Ein prest må ikkje gjera seg urein for landsmennerne sine med å røra noko lik,',
        2: 'minder det er ein av hans næmaste skyldfolk, anten mor eller far eller son eller dotter eller bror,',
        3: 'eller ei syster som var møy og endå høyrde til ætti, med di ho ikkje var burtgift; henne kann han koma nær, um ho ligg lik;',
        4: 'men ei som var gift kona, må han ikkje røyva; for då gjer han seg urein for landsfolket sitt, og vanhelgar seg.',
        5: 'Prestane må ikkje raka seg snaude i kruna, og ikkje stytta skjegget sitt, og ikkje skjera seg i holdet.',
        6: 'Heilage skal dei vera for sin Gud, dei må ikkje vanhelga namnet hans; for det er dei som ber fram eldofferi åt Herren, maten åt deira Gud; di skal dei vera heilage.',
        7: 'Ingen av deim må gifta seg med ei skjøkja eller ei kvinna som er utskjemd, heller ikkje med ei som er skild frå mannen sin; heilag skal presten vera for sin Gud,',
        8: 'og du skal halda honom heilag; for det er han som ber fram maten åt din Gud: heilag skal han vera deg; for eg er heilag, eg, Herren, som helgar dykk.',
        9: 'Og dersom ei prestedotter skjemdar seg med ulivnad, so vanhelgar ho far sin: ho skal brennast på bål.',
        10: 'Den presten som er yver alle brørne sine, han som fær salvingsoljen på hovudet sitt, og vert vigd til øvsteprest og klædd i den heilage bunaden, han må ikkje ganga med uflitt hår, og ikkje riva sund klædi sine.',
        11: 'Han må ikkje ganga inn til noko lik; ikkje far eller mor di heller må han koma nær, etter dei hev andast; for då vert han urein.',
        12: 'Han må ikkje ganga ut or det heilage huset, so han vanhelgar heilagdomen åt sin Gud; for vigsla av Guds salvingsolje er yver honom. Eg er Herren!',
        13: 'Han skal taka ei rein møy til kona.',
        14: 'Ei enkja, eller ei kvinna som er fråskild eller utskjemd, eller ei skjøkja, slik ei må han aldri gifta seg med. Berre ei møy av folket sitt må han egta;',
        15: 'elles vanhelgar han ætti si millom folket. Kom i hug: det er eg, Herren, som hev helga honom!»»',
        16: 'Og Herren tala meir til Moses, og sagde:',
        17: '«Tala til Aron og seg: «Er det nokon av ætti di no eller i komande tider, som hev eit lyte, so må han ikkje ganga innåt og bera fram maten åt sin Gud.',
        18: 'Ingen som det er noko lyte på, må ganga innåt, ingen som er blind eller halt eller haremynt, eller hev ein vanskapt lem',
        19: 'eller ein broten fot eller arm,',
        20: 'eller som er krylryggja eller skinnturr, eller som hev ein kvit flekk på augnesteinen, eller hev skabb eller gardorm eller slit i pungarne.',
        21: 'Ingen etterkomar av Aron, presten, som hev noko lyte, må ganga innåt og bera fram eldofferi åt Herren; det er lyte på honom: han må ikkje ganga innåt og bera fram maten for sin Gud.',
        22: 'Han må nok eta av retterne åt sin Gud, både dei høgheilage og dei heilage;',
        23: 'men etter di det er lyte på honom, må han ikkje ganga fram til forhenget, og ikkje koma innåt altaret; for då vanhelgar han heilagdomarne mine. Kom i hug: det er eg, Herren, som hev helga deim.»»',
        24: 'Og Moses sagde alt dette til Aron og sønerne hans og til heile Israels-lyden.',
    },
    22: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Seg til Aron og sønerne hans at dei lyt sjå seg vel fyre med dei heilage gåvorne som Israels-folket vigjer åt meg, so dei ikkje vanhelgar mitt heilage namn. Eg er Herren!',
        3: 'So skal du segja med deim: «Dersom nokon av ætti dykkar, no eller i framtidi, røyver dei heilage gåvorne som Israels-folket vigjer åt Herren, medan det er noko ureint på honom, so skal han rydjast burt or augnesyni mi. Kom i hug: eg er Herren!',
        4: 'Ingen av etterkomarane hans Aron som er spillsjuk eller hev sådflod, må eta av dei vigde gåvorne, fyrr han er rein att. Kjem ein av deim nær nokon som hev vorte urein av eit lik, eller gjeng sådet frå honom um natti,',
        5: 'eller kjem han innåt noko krek som folk vert ureine av, eller noko menneskje som på ein eller annan måte hev vorte ureint,',
        6: 'hev nokon av deim røyvt noko sovore, so er han vera urein alt til kvelds, og må ikkje eta av dei vigde gåvorne, fyrr han hev lauga likamen sin i vatn.',
        7: 'Når soli hev gladt, er han rein att, og sidan kann han eta av dei vigde gåvorne; for det er maten hans.',
        8: 'Det som er sjølvdaudt eller ihelrive, må han ikkje eta; då vert han urein. Kom i hug: eg er Herren!',
        9: 'Dei skal halda dei bodi eg hev gjeve deim, so dei ikkje ber synd for slike ting og lyt døy for di dei hev vanhelga det som er heilagt. Kom i hug: det er eg, Herren, som hev helga det!',
        10: 'Ingen framand må eta av det som heilagt er. Ingen som er busete eller leigekar hjå ein prest, må smaka på dei vigde rettarne.',
        11: 'Men hev presten kjøpt seg ein tenar for pengar, so kann han eta av deim; like eins dei tenarane som er fødd i huset hjå presten: dei kann eta av maten hans.',
        12: 'Når ei prestedotter er gift med ein framand mann, so må ho ikkje eta av dei heilage offergåvorne.',
        13: 'Men hev ho vorte enkja, eller er skild frå mannen, og ikkje hev born, og ho so kjem attende til far sin og bur i huset heime hjå honom liksom i ungdomen, so kann ho eta av maten åt far sin; men ingen uskyld må eta av den maten.',
        14: 'Hev nokon ete uviljande av dei vigde gåvorne, so skal han gjeva presten lika for det, og leggja attåt femteparten av verdet.',
        15: 'De må ikkje vanhelga dei heilage gåvorne frå Israels-folket - det som dei vigjer åt Herren -',
        16: 'og lata deim føra syndeskuld yver seg med å eta av dei heilage retterne dykkar. Kom i hug: det er eg, Herren, som helgar deim!»»',
        17: 'Og Herren tala atter til Moses, og sagde:',
        18: '«Tala til Aron og sønerne hans og til heile Israels-folket, og seg til deim: «Når nokon av Israels-ætti eller av dei framande i Israel kjem med ei offergåva, anten det er ei som er utlova, eller ei gåva i godvilje som dei vil bera fram til brennoffer åt Herren,',
        19: 'då lyt offeret vera so at de kann tekkjast Herren med det: ein lytelaus ukse eller ver eller bukk.',
        20: 'Noko som det er lyte på, må de ikkje bera fram; for det tekkjest de ikkje Herren med.',
        21: 'Og når nokon ber fram eit takkoffer åt Herren av storfeet eller småfeet, anten det er ein lovnad han vil løysa, eller det er ei gåva i godvilje, so lyt det vera eit lytelaust dyr, dersom offeret skal tekkjast Herren; det må ikkje finnast nokor veila på det.',
        22: 'Dyr som er blinde eller beinbrotne eller skamførde, eller som hev verksår eller skabb eller gardorm, deim må de ikkje bera fram for Herren og leggja på altaret hans til offermat.',
        23: 'Ein ukse eller sau som hev for lange eller for stutte lemer, kann du hava til eit offer i godvilje; men til lovoffer høver dei ikkje.',
        24: 'Gjelde dyr, anten dei er klakka eller kruste eller rivne eller skorne, skal de ikkje bera fram for Herren. Ikkje skal de gjera slikt i dykkar eige land,',
        25: 'og ikkje skal de kjøpa sovorne dyr av framande, og bera dei fram til mat for dykkar Gud; for dei er utskjemde, det er lytedyr: med slike offer vinn de ikkje Guds nåde.»»',
        26: 'Og Herren tala endå meir til Moses, og sagde:',
        27: '«Når ein kalv eller eit lamb eller eit kid er tilkome, skal dei fylgja mor si sju dagar; men frå den åttande dagen og sidan vil Herren tekkjast med deim, i fall de ber dei fram til offermat.',
        28: 'Kui og kalven hennar eller søya og lambet hennar skal de ikkje slagta på ein dag.',
        29: 'Når de ber fram eit lov- og takkoffer, skal de gjera det so at Herren hev hugnad av dykk:',
        30: 'De skal eta det upp same dagen, og ikkje leiva noko av det til morgons. Kom i hug: eg er Herren!',
        31: 'So haldt då bodi mine, og liv etter deim! Eg er Herren:',
        32: 'Vanhelga ikkje mitt heilage namn, men lat det helgast hjå Israels-folket! Kom ihug: eg er Herren, som hev helga dykk,',
        33: 'og som fylgde dykk ut or Egyptarlandet og vil vera dykkar Gud - eg, Herren.»',
    },
    23: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Tala til Israels-folket, og seg til deim: «No skal eg nemna dykk Herrens høgtider, dei dagarne som de skal kalla folket i hop til eit heilagt møte og halda høgtid for meg!',
        3: 'Seks dagar lyt de arbeida og vera onnuge; men den sjuande dagen skal vera heil kviledag, med heilagt møte. Då må de ikkje gjera noko arbeid; i alle heimarne dykkar skal det vera ein kviledag, vigd åt Herren.',
        4: 'Herrens høgtider, dei heilage møti som de skal kalla i hop, kvart på si visse tid, det er desse:',
        5: 'Den fjortande dagen i den fyrste månaden, soleglads bil, tek Herrens påskehelg til.',
        6: 'Og den femtande dagen i den same månaden skal de halda søtebrødhelgi for Herren. I sju dagar skal de eta usyrt brød;',
        7: 'den fyrste dagen skal de halda eit heilagt møte, og må ikkje gjera noko utearbeid,',
        8: 'og alle dei sju dagarne skal de bera fram offermat åt Herren; den sjuande dagen skal de og halda eit heilagt møte, og noko utearbeid må de ikkje gjera då heller.»»',
        9: 'Og Herren tala meir til Moses, og sagde:',
        10: '«Tala til Israels-folket, og seg med deim: «Når de kjem til det landet som eg vil gjeva dykk, og haustar inn kornet der, so skal de koma til presten med det fyrste kornbandet av nygrøda,',
        11: 'og han skal svinga det att og fram for Herrens åsyn, so Herren kann hava hugnad av dykk; dagen etter helgi skal presten svinga kornbandet.',
        12: 'Og same dagen som de svingar kornbandet, skal de bera fram eit årsgamalt lamb som er lytelaust, til brennoffer åt Herren.',
        13: 'Grjonofferet som fylgjer med, skal vera tvo kannor fint mjøl, blanda med olje - då er det ein offerrett åt Herren, som gjev god ange - og drykkofferet ei halv kanne vin.',
        14: 'Og brød eller steikte aks eller rått korn må de ikkje eta fyre den dagen, ikkje fyrr de hev bore fram den gåva som er etla åt dykkar Gud. Det skal vera ei æveleg lov for dykk og etterkomarane dykkar i kvar ein heim.',
        15: 'Frå den fyrste dagen etter helgi, frå den dagen de bar fram kornbandet som skulde svingast for Herrens åsyn, skal de telja sju fulle vikor:',
        16: 'femti dagar skal de telja, til dagen etter den sjuande vika, og då skal de bera fram eit nytt grjonoffer for Herren.',
        17: 'Tvo vigslingsbrød skal de koma med frå heimarne dykkar; i deim skal det vera tvo kannor fint mjøl, og dei skal vera syrte; det skal vera nygrødeoffer åt Herren.',
        18: 'Og attåt brødet skal de bera fram sju årsgamle lytelause lamb og ein ung ukse og tvo verar til brennoffer åt Herren, og det grjonofferet og dei drykkofferi som fylgjer med: det er ein offerrett for Herren, som det angar godt av.',
        19: 'Til syndoffer skal de ofra ein geitebukk, og til takkoffer tvo årsgamle lamb;',
        20: 'deim skal presten svinga att og fram for Herrens åsyn saman med nygrødebrødet; dei skal vigjast åt Herren, og høyra presten til.',
        21: 'Og same dagen skal de kalla folket i hop, og halda eit heilagt møte; de må ikkje gjera noko utearbeid den dagen. Dette skal vera ei æveleg lov for dykk og etterkomarane dykkar i kvar ein heim.',
        22: 'Og når de haustar kornet av åkrane dykkar, skal du ikkje skjera kornet for vel utåt reini, og dei aksi som ligg att etter skurden, skal du ikkje plukka upp; du skal etla deim att åt dei fatige og framande. Kom i hug: eg er Herren, dykkar Gud!»»',
        23: 'Og Herren tala atter til Moses, og sagde:',
        24: '«Tala til Israels-folket og seg: «Den fyrste dagen i den sjuande månaden skal de halda helg; då skal luren ljoma og minna dykk, og de skal halda eit heilagt møte.',
        25: 'Den dagen må de ikkje gjera noko utearbeid, og de skal bera fram offermat for Herren.»»',
        26: 'Og Herren tala meir til Moses, og sagde:',
        27: '«So den tiande dagen i den same sjuande månaden er det soningsdag. Det skal vera ein heilag møtedag for dykk, og de skal fasta og bera fram offermat for Herren.',
        28: 'Den dagen må de ikkje gjera noko arbeid; for det er soningsdag; då skal dei gjera soning for dykk framfor åsyni åt Herren, dykkar Gud.',
        29: 'Alle som ikkje fastar den dagen, skal rydjast ut or ætti si.',
        30: 'Og den som gjer noko arbeid, honom vil eg tyna midt ibland folket hans.',
        31: 'Ikkje det minste grand må de gjera den dagen; det skal vera ei æveleg lov for dykk og etterkomarane dykkar i kvar ein heim.',
        32: 'Ein kvile- og helgedag skal det vera for dykk, og de skal fasta; frå niande dags kvelden i den månaden til kvelden etter skal de halda heilagt.»',
        33: 'Og Herren tala endå meir til Moses, og sagde:',
        34: '«Tala til Israels-folket og seg: «Frå den femtande dagen i den same sjuande månaden skal de halda lauvhyttehelg for Herren i sju dagar.',
        35: 'Den fyrste dagen skal de halda eit heilagt møte, og noko utearbeid må de ikkje gjera.',
        36: 'Sju dagar skal de bera fram offermat for Herren; og den åttande dagen skal de halda eit heilagt møte, og bera fram offermat for Herren. Då er det stor samlingshøgtid, og de må ikkje gjera noko utearbeid.',
        37: 'Dette er dei høgtiderne då de skal kalla folket i hop til heilagt møte og bera fram offer for Herren: brennoffer og grjonoffer, slagtoffer og drykkoffer, kvart til si tid,',
        38: 'umfram Herrens kviledagsoffer, og umfram gåvorne dykkar og alle dei offeri de hev lova, eller kjem til Herren med av dykk sjølve.',
        39: 'Men frå den femtande dagen i den sjuande månaden, når de samlar grøda i hus, skal de høgtida Herrens pilegrimshelg i sju dagar. Den fyrste dagen skal det halda heilag, og den åttande dagen skal det halda heilag.',
        40: 'Og den fyrste dagen skal de taka fagre frukter og palmegreiner og lauvrike buskor og seljekvister, og gleda dykk for Guds åsyn i sju dagar.',
        41: 'Soleis skal de kvart år halda pilegrimshelg for Herren i sju dagar; det skal vera ei æveleg lov for dykk og etterkomarane dykkar. I den sjuande månaden skal de halda den helgi.',
        42: 'Då skal de bu i lauvhyttor i sju dagar; alle som er fødde og borne i Israel, skal bu i lauvhyttor,',
        43: 'so etterkomarane dykkar skal minnast at eg let Israels-sønerne bu i lauvhyttor då eg fylgde deim ut or Egyptarlandet, eg, Herren, deira Gud.»»',
        44: 'Og Moses kunngjorde Herrens høgtider for Israels-folket.',
    },
    24: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Seg med Israels-folket at dei skal koma med skir olje av sundstøytte oljeber til ljosestaken, so lamporne stødt kann setjast upp!',
        3: 'Utanfor tæpet som heng attfor lovtavlekista i møtetjeldet, skal Aron stella lamporne so dei kann lysa for Herrens åsyn frå kveld til morgon, stødt og stendigt; det skal vera ein fast sed hjå dykk og etterkomarane dykkar:',
        4: 'på den bjarte gullstaken skal han skipa lamporne for Herrens åsyn seint og tidleg.',
        5: 'So skal du taka fint mjøl, og baka tolv kakebrød; i kvart brød skal det vera tvo kannor mjøl.',
        6: 'Og deim skal du leggja i tvo rader, seks i kvar rad, på gullbordet, for Herrens åsyn.',
        7: 'Og på kvar rad skal du leggja rein angekvåda; det skal vera eit minningsoffer for brødet, ein offerrett åt Herren.',
        8: 'Kvar helg skal han leggja det brødet fram for Herrens åsyn, stødt og stendigt; det skal vera ei æveleg sambandsgåva frå Israels-borni.',
        9: 'Og Aron og sønerne hans skal få det og eta det på ein heilag stad; for det høyrer til det som er høgheilagt av Herrens offermat, og prestarne skal hava rett til det i all æva.»',
        10: 'Ein som var son til ei israelitisk kona, men hadde ein egyptar til far, gjekk ein gong inn millom Israels-folket, og han og ein av Israels-mennerne kom i trætta med kvarandre i lægret.',
        11: 'Og son til den israelitiske kona - ho heitte Sjelomit Dibrisdotter, og var av Dans-ætti - tok til å banna Guds namn og spotta det.',
        12: 'Då førde dei honom burt til Moses, og sette honom fast til dei kunde få ein orskurd av Herrens munn.',
        13: 'Og Herren tala til Moses, og sagde:',
        14: '«Før spottaren ut or lægret, og alle dei som høyrde på det, skal leggja henderne på hovudet hans, og heile lyden skal steina honom.',
        15: 'Og til Israels-folket skal du segja: «Den som bannar sin Gud, lyt lida for syndi si,',
        16: 'og den som spottar Herrens namn, han skal lata livet; heile lyden skal steina honom i hel; anten han er framand eller fødd og boren i landet, so skal han lata livet, so sant han hev spotta Guds namn.',
        17: 'Slær nokon ein mann i hel, so skal han lata livet.',
        18: 'Den som slær i hel eit krøter, skal gjeva like for det, liv for liv.',
        19: 'Valdar nokon at grannen hans fær skade på likamen, so skal dei gjera det same med honom som han hev gjort med grannen:',
        20: 'brot for brot, auga for auga, tonn for tonn; det meinet han hev gjort ein annan, skal han sjølv få.',
        21: 'Den som slær i hel eit krøter, skal gjeva lika for det; men den som slær i hel eit menneskje, skal lata livet.',
        22: 'Det er same retten for dykk alle, for den framande likso vel som for den som er fødd og boren i landet; for eg, Herren, er dykkar Gud.»»',
        23: 'Og Moses kunngjorde dette for Israels-folket, og dei førde spottaren ut or lægret, og steina honom i hel: Israels-mennerne gjorde som Herren hadde sagt til Moses.',
    },
    25: {
        1: 'Og Herren tala atter til Moses på Sinaifjellet, og sagde:',
        2: '«Tala til Israels-folket, og seg til deim: «Når de kjem til det landet som eg vil gjeva dykk, so skal landet halda helg for Herren og kvila:',
        3: 'Seks år skal du så åkeren din, og seks år skal du kylla vintrei dine, og sanka det som jordi gjev av seg;',
        4: 'men det sjuande året skal vera ei kviletid for landet, ei helg som er vigd åt Herren: då skal du ikkje så åkeren din, og ikkje kylla vintrei.',
        5: 'Det kornet som renn upp av seg sjølv etter fjorgrøda, skal du ikkje skjera, og druvorne på det ukyllte vintreet skal du ikkje sanka: Eit kvileår skal det vera for landet.',
        6: 'Og det som jordi ber i kviletidi, skal vera til føda for dykk alle: for deg og drengen din og tenestgjenta di og leigekaren og buseten som held til hjå deg;',
        7: 'og bufeet ditt og villdyri som er i landet, skal og eta av all den grøda som veks.',
        8: 'So skal du telja fram sju kvileår, sju gonger sju, so tidi som svarar til dei sju kvileåri, vert ni og fyrti år;',
        9: 'og den tiande dagen i den sjuande månaden skal du blåsa i lur; på soningsdagen skal de lata luren ljoma i heile landet dykkar.',
        10: 'Og de skal helga det femtiande året, og lysa ut fridom for alle som i landet bur. Det skal vera eit jubelår for dykk; då skal de koma attende kvar til sin odel og venda heim att kvar til si ætt.',
        11: 'Eit jubelår skal det femtiande året vera for dykk: ikkje skal de så, og ikkje skal de hausta det sjølvsådde kornet, og ikkje skal de sanka druvorne av det ukyllte vintreet.',
        12: 'For det er eit jubelår: det skal vera heilagt for dykk; på marki skal de henta maten etter kvart som de treng honom.',
        13: 'I jubelåret skal kvar få att odelsgarden sin.',
        14: 'Når du sel noko til landsmannen din eller kjøper noko av honom, so skal de ikkje gjera urett mot kvarandre.',
        15: 'Kjøper du jord av honom, so skal du telja dei åri som er lidne frå jubelåret, og han skal rekna etter kor mange åringar det er att.',
        16: 'Etter som det då er mange eller få år att, skal prisen auka eller minka; for det er berre eit visst tal med avlingar han sel deg.',
        17: 'Gjer ikkje urett mot kvarandre; hav age for dykkar Gud! Kom i hug: eg, Herren, er dykkar Gud!',
        18: 'Lyd loverne mine, og haldt bodi mine og liv etter deim, so skal de bu trygt i landet;',
        19: 'landet skal gjeva dykk grøda si, og de skal hava nøgdi å liva av, og sitja der trygt.',
        20: 'Og dersom de spør: «Kva skal me eta i det sjuande året, når me ikkje sår og ikkje samlar inn grøda vår?»',
        21: 'so må de vita at i det sette året vil eg senda dykk mi velsigning, og de skal få so rik ei grøda, at ho rekk til for tri år.',
        22: 'Når de sår i det åttande året, skal de endå eta av fyrrårsavlen; alt til grøda kjem det niande året, skal de leva av den gamle avlen.',
        23: 'Jordi må de ikkje selja for ollo; for det er eg som eig landet; de er berre framande og leiglendingar hjå meg.',
        24: 'Difor skal det i heile landet dykkar gjelda løysingsrett for jord:',
        25: 'Dersom det gjeng ut for grannen din, og han lyt selja noko av garden sin, so skal næmaste odelsmannen koma og løysa att det som skyldingen hans hev selt.',
        26: 'Finst det ingen som kann løysa att jordi for honom, og han sjølv fær so mykje med hand at han kann greida løysingsummen,',
        27: 'so skal han rekna frå dei åri som er lidne sidan han selde, og gjeva den han selde til lika for det som att er; då vert eigedomen hans;',
        28: 'men er han ikkje god til å greida det han skal ut med, so skal jordi høyra kjøparen til alt til jubelåret; i jubelåret vert ho fri og kjem under den gamle eigaren.',
        29: 'Når ein sel eit stovehus i ein by med murar ikring, so gjeld løysingsretten berre for ei tid; so lenge som eit år etter huset vart selt, skal han hava rett til å løysa det att.',
        30: 'Vert ikkje huset attløyst fyrr eit fullt år er lide, so skal det - so framt det ligg i ein by med murar ikring - falla under den som hev kjøpt det, og høyra honom og etterkomarane hans til for godt, og det vert ikkje fritt i jubelåret.',
        31: 'Men husi i småbyar som det ikkje er murar ikring, skal reknast til landet; dei kann løysast att, og i jubelåret vert dei frie.',
        32: 'Er det levitbyarne det gjeld, husi i dei byarne som høyrer Levi-sønerne til, so varer løysingsretten for alle tider.',
        33: 'Og um nokon av Levi-sønerne ikkje løyser att eit hus han hev selt, so vert huset fritt i jubelåret, so framt det ligg i fedrebyen hans; for husi i dei byarne som høyrer levitarne til, er deira odel millom Israels-folket.',
        34: 'Heller ikkje må beitemarki kring byarne deira seljast; ho skal høyra deim til for alle tider.',
        35: 'Når det gjeng ut for grannen din, og han ikkje kann greida seg lenger, so skal du halda handi yver honom, og han skal liva hjå deg som ein framand eller busete.',
        36: 'Du må ikkje taka renta eller yvermål av honom; du skal hava age for din Gud, og lata grannen din liva med deg.',
        37: 'Du må ikkje låna honom pengar på den måten at han skal gjeva deg renta, eller mat på den måten at han skal gjeva deg noko attpå.',
        38: 'Kom i hug: Eg er Herren, dykkar Gud, som fylgde dykk ut or Egyptarlandet og vil gjeva dykk Kana’ans-landet og vera dykkar Gud.',
        39: 'Når grannen din vert utarma og lyt selja seg til deg, so skal du ikkje lata honom gjera slavearbeid for deg.',
        40: 'Han skal vera hjå deg som ein leigekar eller busete, og arbeide hjå deg til jubelåret;',
        41: 'då skal han flytja frå deg, både han og borni hans, og fara heim att til ætti si og fedregarden.',
        42: 'For dei er mine tenarar, eg henta deim ut or Egyptarlandet; dei må ikkje seljast som ein sel ein slave.',
        43: 'Du må ikkje vera hard med deim; du skal hava age for din Gud.',
        44: 'Vil du få deg tenestdrengjer eller tenestgjentor som skal vera din eigedom, so kann du kjøpa både drengjer og gjentor av heidningarne som bur rundt ikring dykk,',
        45: 'og like eins av borni åt innflytjarane som held til hjå dykk; av deim og etterkomarane deira som bur hjå dykk og er fødde i landet dykkar, kann de kjøpa dykk tenarar som de må eiga,',
        46: 'og kann lata borni dykkar få i arv etter dykk med full eigedomsrett; deim kann de bruka til slavar so lenge de vil; men brørne dine, Israels-borni, må du ikkje gjera deg til herre yver - bror yver bror!',
        47: 'Når ein framand eller innflutt mann hjå deg kjem til velstand hjå dykk, og landsmannen din som bur innmed han, vert utarma, og lyt selja seg til den innflutte framande mannen, eller til ein som er runnen av framand rot,',
        48: 'so kann han løysast ut att, etter han hev selt seg. Ein av brørne hans lyt då løysa honom ut,',
        49: 'eller farbroren eller son åt farbroren eller ein annan av det næmaste skyldfolket i ætti hans; og fær han utkoma til det, so kann han løysa seg ut sjølv.',
        50: 'Når han då gjer upp med den han hev selt seg til, skal dei rekna ut tidi frå det året han selde seg og til jubelåret: kjøpesummen skal bytast med åretalet, og det skal vera som han hadde vore leigekar hjå honom og arbeidt etter dagen.',
        51: 'Er det endå mange år att, so skal han i utløysnad leggja so mykje av kjøpesummen som svarar til dei åri;',
        52: 'og er det få år att til jubelåret, so skal han gjera upp med honom for deim; han skal i utløysnad gjeva det som svarar til dei åri han er attskuldig.',
        53: 'Han skal vera jamgod med ein leigekar som arbeider hjå ein mann år for år; du skal ikkje tola at dei fer hardt med honom.',
        54: 'Vert han ikkje utløyst på den måten som nemnt er, so vert han fri i jubelåret, både han og borni hans.',
        55: 'For meg høyrer Israels-sønerne til, og er tenarane mine - mine tenarar er dei; eg henta deim ut or Egyptarlandet, eg, Herren, dykkar Gud.',
    },
    26: {
        1: 'De skal ikkje gjera dykk avgudar, og ikkje reisa gudebilæte eller minnestolpar eller setja bilætsteinar i landet dykkar og kasta dykk på kne for deim. Eg, Herren, er dykkar Gud.',
        2: 'Helgarne mine skal de halda, og hava age for heilagdomen min. Kom i hug: eg er Herren!',
        3: 'Lyder de no mine lover og agtar på ordi eg tala, og gjer de som eg hev sagt dykk,',
        4: 'so skal eg senda dykk regnet i rette tid, når det treng det, og jordi skal gjeva si grøda, og hagetrei si alda.',
        5: 'Treskjartidi skal vera hjå dykk til vinonni byrjar, og vinonni vara til vinteren, og de skal eta dykk mette av maten som de hev avla, og liva trygge i landet.',
        6: 'Fred vil eg gjeva i landet: de skal liggja og kvila, og ingen skal skræma dykk upp; udyri, deim vil eg øyda, so dei kverv burt ifrå landet, og sverd skal’kje herja i riket;',
        7: 'uvenerne skal de elta, og dei skal stupa framfor dykk:',
        8: 'fem av dykk skal jaga eit hundrad, og hundrad jaga ti tusund, og fiendarne falla for sverdet.',
        9: 'Med milda vil eg dykk møta, og lata dykk aukast og veksa og signa sambandet med dykk.',
        10: 'Fjorgamalt korn skal de eta, til dess de lyt rydja det undan, so de fær rom åt det nye.',
        11: 'Eg vil bu og byggja ibland dykk, og aldri leidast utav dykk.',
        12: 'Imillom dykk vil eg ferdast, og dykkar Gud vil eg vera, og de skal vera mitt folk.',
        13: 'Eg er dykkar Gud, eg, Herren, som henta dykk ut or Egyptarlandet, der som de træla for andre; eg braut sund stengern’ i oket, so de kunde ganga rake.',
        14: 'Men vil de’kje høyra på meg, og gjer de’kje alt det eg baud dykk,',
        15: 'mismæter de mine rettar og leidest loverne mine, so de ikkje gjer som eg sagde, og bryt de sambandet med meg,',
        16: 'so gjev eg dykk likt for like: då søkjer eg dykk med fælska, med sott som tærer og brenner, sykja som sløkkjer ut augo og syg magti or livet. Til fånyttes sår de ut kornet; for uvenern’ et det de avlar.',
        17: 'Eg kvesser augo imot dykk: for fienden skal de rjuka, uvenen skal trakka dykk ned; de skal røma, um ingen er etter dykk.',
        18: 'Og vil de endå’kje lyda, so skal eg refsa dykk meir, sju gonger, for synderne dykkar.',
        19: 'Eg bryt dykkar ovmod og magt: eg gjer dykkar himmel som jarn, og jordi dykkar som kopar.',
        20: 'Då øyder de nyttelaust krafti; for jordi gjev ingi grøda, og trei gjev ingi alda.',
        21: 'Og gjer de meg endå imot, og vil de’kje høyra på meg, so slær eg dykk endå sju gonger, som synderne dykkar er verde.',
        22: 'Imot dykk sender eg udyr som ranar borni ifrå dykk, og drep ned bufeet dykkar, og veld at de tynnest i talet, so vegarne dykkar vert aude.',
        23: 'Og let de dykk endå’kje tukta, men driv på og gjer meg imot,',
        24: 'so gjer eg og dykk imot, og slær dykk endå sju gonger for alt det som de hev synda;',
        25: 'eg sender eit sverd yver dykk, som skal hemna pakti de braut; og samlar de dykk i byarn’, so sender eg sott inn ibland dykk, og de skal falla i fiendehand.',
        26: 'Eg skal minka soleis på maten, som var dykkar styrk og studnad, at tie konor skal steikja brødet åt dykk i ein omn; dei skal gjeva det att etter vegt, og de skal’kje få eta dykk mette.',
        27: 'Og høyrer de endå’kje på meg, og herder de på og trassar,',
        28: 'so fer eg imot dykk med vreide, og refsar dykk endå sju gonger for alle syndern’ de gjorde.',
        29: 'Då skal de nøydast til eta kjøtet av sønerne dykkar og kjøtet av dykkar døtter.',
        30: 'Eg skal øyda høgderne dykkar, og rydja solstolparne ut, og kasta dykkar eigne lik på liki av skarnsgudarne dykkar; for de byd mitt hjarta imot.',
        31: 'Eg vil leggja byarn’ i røys, og riva templi ned, og vil ikkje ansa angen som stig upp frå offeri dykkar;',
        32: 'eg skal gjera landet so audt, at fiendarne som bur der skal fæla.',
        33: 'Og dykk skal eg spreida bland folki; med drege sverd skal eg elta dykk, og landet dykkar skal verta ei audn, og byarne skal verta røysar.',
        34: 'Då skal landet få njota si kvild, alt med det lyt liggja i øyde og de er i fiendelandet - ja då skal landet få kvila og halda helgerne sine;',
        35: 'alt med det ligg audt, skal det kvila; då skal det få seg den helgekvildi det ikkje fekk i kvileåri, so lenge de endå budde der.',
        36: 'Men dei av dykk som er att, skal eg gjeva slik rædsla i hjarta, med dei held til i fiendelandi, at ljoden av eit fjukande lauv skal skræma deim upp og jaga deim av, som når ein rømer for sverdet; dei skal falla, um ingen er etter deim.',
        37: 'Dei skal snåva og detta, ein yver hin, som dei hadde sverdet i hælarn’, endå det er ingen som elter. De skal ikkje stå dykk mot uvenern’ dykkar,',
        38: 'men ganga til grunns millom heidningarne, og fiendelandet skal tæra dykk upp.',
        39: 'Og dei av dykk som endå er att, skal visna burt i fiendelandi for broti som dei hev gjort, og for broti åt federne sine; dei skal folna burt liksom dei.',
        40: 'Då skal dei stå til sine brot og broti åt sine feder, at dei fall ifrå meg, og sveik meg, og gjorde meg tvert imot,',
        41: 'so eg og laut stå deim imot, og dreiv deim til fiendelandet - og bøygjer dei så sine hjarto, so harde og stride dei er, og fær dei då kvitta si skuld,',
        42: 'Og so skal eg minnast mitt samband med Jakob og Isak og Abram, og landet skal eg og minnast.',
        43: 'Men landet lyt fyrst vera kvitt deim, og njota helgarne sine med det ligg audt etter deim; og dei lyt bøta si skuld, etter di dei vanda mi lov, og bodet mitt baud deim imot.',
        44: 'Men endå um det er so, og dei er i fiendelandet, vil eg ikkje vanda deim reint eller skjota deim heiltupp ifrå meg: eg vil ikkje rydja deim ut og brjota sambandet med deim; for eg, Herren, er deira Gud.',
        45: 'Eg vil minnast mi pakt med dei gamle, som eg henta ut or Egyptarland midt for augo på heidningefolki, og var deira Gud, eg, Herren!»»',
        46: 'Dette er dei bodi og rettarne og loverne som Herren sette millom seg og Israels-folket på Sinaifjellet og let Moses kunngjera for deim.',
    },
    27: {
        1: 'Og Herren tala atter til Moses, og sagde:',
        2: '«Tala til Israels-folket, og seg til deim: «Når ein hev lova å vigja seg sjølv eller eit anna menneskje til Herren, og sidan vil løysa seg frå lovnaden med penger, so skal du verdsetja den som er burtlova:',
        3: 'Verdet på ein mann som er millom tjuge og seksti år, skal vera femti sylvdalar i heilag mynt;',
        4: 'er det eit kvende, so skal du setja verdet til tretti dalar.',
        5: 'Eit menneskje som er millom fem år og tjuge år, skal du setja i tjuge dalar dersom det er ein kar, og i ti dalar dersom det er eit kvende.',
        6: 'Er det eit barn millom ein månad og fem år, so skal verdet på ein gut vera fem sylvdalar, og på ei gjenta tri sylvdalar.',
        7: 'Deim som er seksti år eller meir, skal du setja i femtan dalar i fall det er menner, og i ti dalar i fall det er kvende.',
        8: 'Er nokon so fatig at han ikkje kann greida ut pengarne, so skal dei koma til presten med honom, og presten skal setja verdet etter hans utkoma som gjorde lovnaden.',
        9: 'Er det eit dyr som er burtlova, eit av deim som folk ber fram til offer for Herren, so skal alt ein gjev Herren av slikt, reknast for heilagt.',
        10: 'Ein må ikkje byta det um eller gjeva eit anna dyr i staden, korkje eit ringt for eit godt eller eit godt for eit ringt. Byter ein det like vel i eit anna dyr, so skal båe tvo gjelda for heilage.',
        11: 'Men er det eit ureint dyr, eit av deim ein ikkje kann gjeva Herren i offergåva, so skal det leidast fram for presten,',
        12: 'og presten skal verdsetja det, etter som det er til, godt eller ringt; det som presten set det i, det skal vera prisen på det.',
        13: 'Vil eigaren løysa det att, so lyt han leggja femteparten meir enn det er verdsett til.',
        14: 'Når ein hev lova å vigja huset sitt til Herren, so skal presten verdsetja det etter som det er til, godt eller ringt, og det som presten set det i, skal gjelda for rette verdet.',
        15: 'Vil den som hev lova burt huset løysa det att, so skal han leggja femteparten yver det verdet; då vert det hans.',
        16: 'Når ein hev lova burt noko av odelsjordi si til Herren, so skal verdet retta seg etter sådmengdi: ein åker på halvtridje tunnesåd bygg skal svara til femti sylvdalar.',
        17: 'Hev han lova burt jordi alt ifrå jubelåret, so skal det verdet gjelda fullt.',
        18: 'Men er det etter jubelåret han hev lova henne burt, so skal presten rekna ut verdet etter dei åri som er att til komande jubelår, og prisen skal setjast ned etter måten.',
        19: 'Hev ein lova Herren eit stykke av jordi si, og sidan vil løysa det, skal han leggja femteparten yver verdet, so skal han få det.',
        20: 'Løyser han det ikkje, og like vel sel det til ein annan, so kann det ikkje løysast meir;',
        21: 'når då jubelåret kjem, og jordi vert fri, skal ho høyra Herrens heilagdom til, liksom jord som er vigsla; presten skal hava eigedomsretten til henne.',
        22: 'Når ein hev lova Herren eit stykke jord som han hev kjøpt, og som ikkje er hans odel,',
        23: 'so skal presten rekna ut verdet til komande jubelår, og mannen skal greida ut pengarne med det same, og vigja deim åt Herren.',
        24: 'I jubelåret fell jordi attende til den han kjøpte av, og som hev odelen.',
        25: 'All verdsetjing skal vera i heilag mynt, etter tjuge gera i dalaren.',
        26: 'Det som er frumbore i buskapen, kann ikkje lovast burt; etter di det er frumbore, er det longe Herrens eigedom; anten det er storfe eller småfe, so høyrer det Herren til.',
        27: 'Er det ureine dyr, so kann ein løysa deim att etter verdet, men lyt då leggja attåt femteparten; vert dei ikkje attløyste, so kann dei seljast for verdet.',
        28: 'Det som ein vigslar åt Herren av eigedomen sin, anten det er folk eller fe eller odelsjord, det kann ikkje seljast og ikkje løysast att; alt som er vigsla, er høgheilagt og høyrer Herren til.',
        29: 'Ingen mann som er bannstøytt, kann verta attløyst; han lyt lata livet.',
        30: 'All tiend av jordi, av grøda på marki og av alda på trei, høyrer Herren til, og til Herren skal ho vigjast.',
        31: 'Vil ein løysa att noko av tiendi, skal han leggja femteparten yver verdet.',
        32: 'Og av alt bufeet, både stort og smått, alt som kjem under hyrdingstaven, skal tiande kvart dyr vigjast til Herren.',
        33: 'Ein skal ikkje sjå etter um det er godt eller ringt, og ikkje byta det um. Vert det bytt i eit anna dyr, so skal dei høyra heilagdomen båe, og kann ikkje verta attløyste.»»',
        34: 'Dette var dei loverne som Herren gav Moses på Sinaifjellet og baud honom kunngjera for Israels-folket.',
    },
}
